    if ((m = str.match(/^この【宣言】能力のコストによって【カットイン】を持つ【([^】]+?)】のカードが(\d+)枚以上リムーブされた場合$/))) return ctx => (ctx.milled || []).filter(cid => { const d = CARD_BY_ID.get(cid); return d && cardHasColor(d, m[1]) && cardHasAnyCutinAbility(d); }).length >= Number(m[2]);
