    if ((m = v.match(/^アクティブにするか、ターン終了時まで〚([^〛]+)〛を与える$/))) return { label: `アクティブか〚${m[1]}〛`, apply: (ctx, owner, k, done) => DC.choose2(ctx.side, ctx.srcUid, { label: 'アクティブにする', run: () => { recordEvent({ type: 'activateChar', side: owner, uid: k }); done(); } }, { label: `ターン終了時まで〚${m[1]}〛を与える`, run: () => { recordEvent({ type: 'tempKeywordGrant', side: owner, targetUid: k, keyword: m[1] }); done(); } }) };
