  // 【現場リムーブ時】：個別の処理に当たらなかった効果文を汎用インタプリタで実行する
  function geeFieldRemoveFallback(side, removedCard, start, viaContact){
    if (replayMode || match.events.length > start || geeUiBusy()) return;
    const parts = [];
    for (const l of plainText(removedCard.cardId).split('\n').map(x => x.trim()).filter(Boolean)) {
      const tags = (l.match(/^((?:【(?!(?:青|赤|黄|緑|白|黒)】)[^】]*】)*)/) || ['', ''])[1];
      if (!tags.includes('【現場リムーブ時】')) continue;
      const steps = geeCompile(l.slice(tags.length));
      if (!steps) return;
      parts.push({ tags, steps });
    }
    if (!parts.length) return;
    const ctx = { side, srcUid: removedCard.uid, srcCardId: removedCard.cardId, viaContact: !!viaContact };
    let pi = 0;
    const nextPart = () => {
      if (pi >= parts.length) return;
      const part = parts[pi++];
      if (!tagsOk(side, part.tags)) { nextPart(); return; }
      setTimeout(() => geeRun(part.steps, ctx, nextPart), 700);
    };
    nextPart();
  }
  // 【変装時】の効果文(個別の表に当たらないもの)
  const geeDisguiseCache = new Map();
