          onPick: ks => { if (!ks[0]) return; ctx.costCardId = uidToCardId(ks[0]); if (reveal) triggerHandRevealed(ctx.side, ctx.costCardId); else recordEvent({ type: 'handDiscard', side: ctx.side, uid: ks[0] }); next(); },
