    if ((m = str.match(/^相手の現場にいるキャラ1枚につき、デッキのカードを上から(\d+)枚リムーブする$/))) { const per = Number(m[1]); return { avail: ctx => match[ctx.side].deckPile.length >= per * match[otherSide(ctx.side)].field.length, pay: (ctx, next) => { const n = per * match[otherSide(ctx.side)].field.length; ctx.milled = match[ctx.side].deckPile.slice(0, n).map(c => c.cardId); if (n > 0) recordEvent({ type: 'millSelf', side: ctx.side, count: n }); next(); } }; }
