  const geeCaseDeclCache = new Map();
  // 事件カードの【解決編】【宣言】〚コスト〛：効果 を、汎用インタプリタ(GEE)の宣言定義から組み立てる
  function geeCaseDeclare(cardId){
    if (geeCaseDeclCache.has(cardId)) return geeCaseDeclCache.get(cardId);
    let res = null;
    const d = CARD_BY_ID.get(cardId);
    if (d && d.card_type === '事件' && d.ability_text) {
      plainText(cardId).split(String.fromCharCode(10)).map(l => l.trim()).filter(Boolean).forEach((line, li) => {
        if (res) return;
        const tags = (line.match(/^((?:【(?!(?:青|赤|黄|緑|白|黒)】)[^】]*】)*)/) || ['', ''])[1];
        if (!tags.includes('【宣言】') || !tags.includes('【解決編】')) return;
        const gd = geeBuildDeclare(cardId, line, tags, li);
        if (!gd) return;
        const short = (line.slice(tags.length).replace(/^〚.+?〛：/, '').split('。')[0] || '事件の能力').slice(0, 24);
        res = {
          def: { label: () => '宣言：' + short, check: side => gd.check(side, match[side].case.uid), run: (side, caseUid) => gd.run(side, caseUid) },
          params: { faceUpCount: 0 },
        };
      });
    }
    geeCaseDeclCache.set(cardId, res);
    return res;
  }
  function getGenericCaseDeclare(cardId){
    const t = romanceText(cardId);
    const tp = plainText(cardId);
    for (const def of CASE_DECLARES) {
      const m = t.match(def.re) || tp.match(def.re);
      if (m) return { def, params: def.parse(m) };
    }
    return geeCaseDeclare(cardId);
  }
  function canDeclareGenericCase(side){
    if (!isMyMainPhase(side)) return { ok: false, reason: '手番のメインフェイズでのみ使用できます' };
    const s = match[side];
    if (!s.case) return { ok: false, reason: '' };
    const entry = getGenericCaseDeclare(s.case.cardId);
    if (!entry) return { ok: false, reason: '' };
    if (!s.case.resolved) return { ok: false, reason: '解決編でのみ使用できます' };
    if (match.turn.declaredAbilityUids.includes(s.case.uid)) return { ok: false, reason: 'このターンはすでに使用しました' };
    const faceDownCount = s.evidence.filter(ev => !ev.faceUp).length;
    // faceUpCount===-1：「1つ以上表向きにする」のような可変コスト(最低1つ必要)
    if (entry.params.faceUpCount === -1) {
      if (faceDownCount < 1) return { ok: false, reason: '裏向きの証拠がありません' };
    } else if (faceDownCount < entry.params.faceUpCount) {
      return { ok: false, reason: `裏向きの証拠が足りません（必要：${entry.params.faceUpCount}）` };
    }
    const why = entry.def.check ? entry.def.check(side, entry.params) : '';
    return why ? { ok: false, reason: why } : { ok: true, reason: '' };
  }
  function declareGenericCase(side){
    if (!canDeclareGenericCase(side).ok) return;
    const s = match[side];
    const entry = getGenericCaseDeclare(s.case.cardId);
    const caseUid = s.case.uid;
    match.turn.declaredAbilityUids.push(caseUid);
    flashCaseCard(side);
    if (entry.params.faceUpCount === -1) {
      const faceDownCount = s.evidence.filter(ev => !ev.faceUp).length;
      startEvidencePick(side, caseUid, 'toFaceUp', faceDownCount, flippedUids => {
        entry.def.run(side, caseUid, entry.params, flippedUids);
      }, 1);
    } else if (entry.params.faceUpCount > 0) {
      startEvidencePick(side, caseUid, 'toFaceUp', entry.params.faceUpCount, flippedUids => {
        entry.def.run(side, caseUid, entry.params, flippedUids);
      }, entry.params.faceUpCount);
    } else {
      entry.def.run(side, caseUid, entry.params);
    }
  }

  // 事件「愛しい愛しい…宿敵さん？」：〚痕跡〛の発見状況によって選べる選択肢が変わる
  function getCaseTraceDeclare(cardId){
    return romanceText(cardId).includes(
      '【解決編】【宣言】【ターン1】以下から1つ選んで行う。\n・〚痕跡［未発見］〛の場合、自分の裏向きの証拠を1つ表向きにしてもよい。そうした場合、相手のデッキのカードを上から2枚リムーブする。\n・〚痕跡［発見済み］〛で、自分の現場に【赤】と【黒】のキャラがいる場合、自分の裏向きの証拠を3つ表向きにしてもよい。そうした場合、レベル7以下のスリープ状態のキャラを1枚まで選び、リムーブする。'
    );
  }
  function caseTraceModes(side){
    const s = match[side];
    const hasRed = s.field.some(c => cardHasColor(defOfInst(c), '赤'));
    const hasBlack = s.field.some(c => cardHasColor(defOfInst(c), '黒'));
    return { opt1: !s.trace, opt2: s.trace && hasRed && hasBlack };
  }
  function canDeclareCaseTrace(side){
    if (!isMyMainPhase(side)) return { ok: false, reason: '手番のメインフェイズでのみ使用できます' };
    const s = match[side];
    if (!s.case || !getCaseTraceDeclare(s.case.cardId)) return { ok: false, reason: '' };
    if (!s.case.resolved) return { ok: false, reason: '解決編でのみ使用できます' };
    if (match.turn.declaredAbilityUids.includes(s.case.uid)) return { ok: false, reason: 'このターンはすでに使用しました' };
    const modes = caseTraceModes(side);
    if (!modes.opt1 && !modes.opt2) return { ok: false, reason: 'どちらの条件も満たしていません' };
    return { ok: true, reason: '' };
  }
  function declareCaseTrace(side){
    if (!canDeclareCaseTrace(side).ok) return;
    const s = match[side];
    const caseUid = s.case.uid;
    match.turn.declaredAbilityUids.push(caseUid);
    flashCaseCard(side);
    const modes = caseTraceModes(side);
    openChoice({
      title: '以下から1つ選んで行う', sourceCardId: s.case.cardId, min: 1,
      items: [
        { key: 'opt1', label: '〚痕跡［未発見］〛：証拠を1つ表向き→相手のデッキ上から2枚リムーブ', disabled: !modes.opt1 },
        { key: 'opt2', label: '〚痕跡［発見済み］〛：証拠を3つ表向き→レベル7以下のスリープ状態をリムーブ', disabled: !modes.opt2 },
      ],
      onDone: keys => {
        if (keys[0] === 'opt1') {
          const faceDownCount = s.evidence.filter(ev => !ev.faceUp).length;
          openChoice({
            title: '証拠を表向きにする', sourceCardId: s.case.cardId, min: 1,
            hint: '自分の裏向きの証拠を1つ表向きにしてもよい。',
            items: [{ key: 'yes', label: '表向きにする', disabled: faceDownCount < 1 }, { key: 'no', label: 'しない' }],
            onDone: ks => {
              if (ks[0] !== 'yes') return;
              startEvidencePick(side, caseUid, 'toFaceUp', 1, () => {
                const oppSide = otherSide(side);
                const n = Math.min(2, match[oppSide].deckPile.length);
                if (n > 0) sequentialMill(oppSide, n, null);
              }, 1);
            },
          });
        } else if (keys[0] === 'opt2') {
          const faceDownCount = s.evidence.filter(ev => !ev.faceUp).length;
          openChoice({
            title: '証拠を表向きにする', sourceCardId: s.case.cardId, min: 1,
            hint: '自分の裏向きの証拠を3つ表向きにしてもよい。',
            items: [{ key: 'yes', label: '表向きにする', disabled: faceDownCount < 3 }, { key: 'no', label: 'しない' }],
            onDone: ks => {
              if (ks[0] !== 'yes') return;
              startEvidencePick(side, caseUid, 'toFaceUp', 3, () => {
                openChoice({
                  title: 'リムーブ', sourceCardId: s.case.cardId,
                  hint: 'レベル7以下のスリープ状態のキャラを1枚まで選び、リムーブします。',
                  items: fieldItems(['self', 'opponent'], (c, inst) => !!inst.sleeping && c.level != null && c.level <= 7, side),
                  min: 0, max: 1, confirmText: 'リムーブする',
                  onDone: ks2 => { if (ks2[0]) removeCharByEffect(side, caseUid, fieldOwnerOf(ks2[0]), ks2[0]); },
                });
              }, 3);
            },
          });
        }
      },
    });
  }

  // ---- 誘発：自分がネクストヒントで【色】のカードを使用したとき(江戸川コナン＆工藤新一) ----
  function triggerNextHintUseAbilities(side, playedDef){
    if (!match.turn || match.turn.activeSide !== side) return;
    const re = /【パートナー([^】]+?)】【ターン1】自分がネクストヒントで【([^】]+?)】のカードを使用したとき、AP(\d+)以下のキャラを1枚まで選び、デッキの下に移す。/;
    // このカードのテキストには「パートナーエリアでも発動する」旨の記載がないため、
    // パートナーエリアに移動している間は発動しない(現場にいるものだけを見る)
    const src = match[side].field.find(inst => {
      const m = romanceText(inst.cardId).match(re);
      return m && partnerHasColor(side, m[1]) && cardHasColor(playedDef, m[2])
        && !match.turn.declaredAbilityUids.includes(romanceDeclareKey(inst.uid, 'nextHint'));
    });
    if (src) {
      const m = romanceText(src.cardId).match(re);
      const apLimit = Number(m[3]);
      match.turn.declaredAbilityUids.push(romanceDeclareKey(src.uid, 'nextHint'));
      showCardSpotlight(src.cardId);
      openChoice({
        title: '誘発効果', sourceCardId: src.cardId,
        hint: `ネクストヒントで【${m[2]}】のカードを使用しました。AP${apLimit}以下のキャラを1枚まで選び、デッキの下に移せます（どちらの現場でも可）。`,
        items: fieldItems(['self', 'opponent'], (c, inst, sk) => effectiveAp(match, inst, sk) <= apLimit, side),
        min: 0, max: 1, confirmText: 'デッキの下に移す',
        onDone: keys => {
          if (keys[0]) recordEvent({ type: 'fieldToDeckBottom', side: fieldOwnerOf(keys[0]), uid: keys[0] });
        },
      });
      return;
    }
    // 江戸川コナン(0260)：【ターン1】自分がネクストヒントで手札を使用したとき、
    // デッキの上からN枚見て、〚特徴［X］〛のキャラを1枚まで手札に加え、残りを好きな
    // 順番でデッキの下に移す
    const re260 = /^【ターン1】自分がネクストヒントで手札を使用したとき、自分のデッキのカードを上から(\d+)枚見る。その中から〚特徴［([^］]+)］〛のキャラを1枚まで公開して手札に加え、残りを好きな順番でデッキの下に移す。$/m;
    const src260 = match[side].field.find(inst => {
      const m = romanceText(inst.cardId).match(re260);
      return m && !match.turn.declaredAbilityUids.includes(romanceDeclareKey(inst.uid, 'nextHint'));
    });
    if (src260) {
      const m = romanceText(src260.cardId).match(re260);
      const count = Number(m[1]), trait = m[2];
      match.turn.declaredAbilityUids.push(romanceDeclareKey(src260.uid, 'nextHint'));
      showCardSpotlight(src260.cardId);
      startDeckPeek(side, src260.uid, { count, filter: c => c.card_type === 'キャラ' && cardHasTrait(c, trait), rest: 'bottom' });
      return;
    }
    // 江戸川コナン(R)：【パートナー青】【ターン1】自分がネクストヒントで手札を使用した
    // とき、そのカードのレベル以下のレベルのキャラを1枚まで選び、デッキの下に移す
    // (色の縛りがなく、使用したカード自身のレベルがそのまま上限になる)
    const re2 = /【パートナー([^】]+?)】【ターン1】自分がネクストヒントで手札を使用したとき、そのカードのレベル以下のレベルのキャラを1枚まで選び、デッキの下に移す。/;
    const src2 = match[side].field.find(inst => {
      const m = romanceText(inst.cardId).match(re2);
      return m && partnerHasColor(side, m[1])
        && !match.turn.declaredAbilityUids.includes(romanceDeclareKey(inst.uid, 'nextHint'));
    });
    if (src2 && playedDef.level != null) {
      const levelMax = playedDef.level;
      match.turn.declaredAbilityUids.push(romanceDeclareKey(src2.uid, 'nextHint'));
      showCardSpotlight(src2.cardId);
      openChoice({
        title: '誘発効果', sourceCardId: src2.cardId,
        hint: `ネクストヒントでレベル${levelMax}の「${cardName(playedDef.id)}」を使用しました。レベル${levelMax}以下のキャラを1枚まで選び、デッキの下に移せます（どちらの現場でも可）。`,
        items: fieldItems(['self', 'opponent'], c => c.level != null && c.level <= levelMax, side),
        min: 0, max: 1, confirmText: 'デッキの下に移す',
        onDone: keys => {
          if (keys[0]) recordEvent({ type: 'fieldToDeckBottom', side: fieldOwnerOf(keys[0]), uid: keys[0] });
        },
      });
    }
  }

  // ---- デッキクリック時のメニュー(現状は「1枚ドロー」のみ) ----
  let openDeckMenuSide = null;
  function toggleDeckMenu(side){
    if (replayMode || actionState) return;
    openDeckMenuSide = openDeckMenuSide === side ? null : side;
    renderDeckMenus();
  }
  function closeDeckMenu(){
    openDeckMenuSide = null;
    renderDeckMenus();
  }
  function renderDeckMenus(){
    ['opponent', 'self'].forEach(sideKey => {
      const zone = document.querySelector(`.zone[data-side="${sideKey}"]`);
      const menu = zone.querySelector('.pm-deck .deck-menu');
      if (menu) menu.style.display = openDeckMenuSide === sideKey ? 'block' : 'none';
    });
  }

  // ---- FILEエリアクリック時のメニュー(ネクストヒント) ----
  let openFileMenuSide = null;
  function toggleFileMenu(side){
    if (replayMode || mulliganPhase || actionState) return;
    openFileMenuSide = openFileMenuSide === side ? null : side;
    renderFileMenus();
  }
  function closeFileMenu(){
    openFileMenuSide = null;
    renderFileMenus();
  }
  function renderFileMenus(){
    ['opponent', 'self'].forEach(sideKey => {
      const zone = document.querySelector(`.zone[data-side="${sideKey}"]`);
      const menu = zone.querySelector('.pm-file .file-menu');
      if (menu) menu.style.display = openFileMenuSide === sideKey ? 'block' : 'none';
    });
  }
  // ---- リムーブエリアクリック時のメニュー(一覧を表示) ----
  let openRemoveMenuSide = null;
  function toggleRemoveMenu(side){
    if (replayMode || mulliganPhase || actionState) return;
    openRemoveMenuSide = openRemoveMenuSide === side ? null : side;
    renderRemoveMenus();
  }
  function closeRemoveMenu(){
    openRemoveMenuSide = null;
    renderRemoveMenus();
  }
  function renderRemoveMenus(){
    ['opponent', 'self'].forEach(sideKey => {
      const zone = document.querySelector(`.zone[data-side="${sideKey}"]`);
      const menu = zone.querySelector('.pm-remove .remove-menu');
      if (menu) menu.style.display = openRemoveMenuSide === sideKey ? 'block' : 'none';
    });
  }
  // リムーブエリアにあるすべてのカードを、選択はできない一覧として表示する
  // (openChoiceの汎用ダイアログをmax:0(選べない)で流用し、閲覧専用にする)
  function showRemoveList(side){
    const cards = match[side].remove;
    openChoice({
      title: `${sideLabelOf(side)}のリムーブエリア（${cards.length}枚）`, forceShow: true,
      hint: cards.length > 0 ? 'リムーブエリアにあるカードの一覧です。' : 'リムーブエリアにカードはありません。',
      items: cards.map(c => ({ key: c.uid, cardId: c.cardId })),
      min: 0, max: 0, skipText: '閉じる',
    });
  }
  document.addEventListener('click', () => { closeDeckMenu(); closeCardMenu(); closeFileMenu(); closeRemoveMenu(); });

  // deckPeekOverlay(登場時効果／ネクストヒント)で、カードを選んで「はい/いいえ」等の
  // 選択肢が出ている状態のとき、背景(ダイアログの外)をクリックしたら選択を解除する
  document.getElementById('deckPeekOverlay').addEventListener('click', (e) => {
    if (e.target.id !== 'deckPeekOverlay') return; // ダイアログ内のクリックでは発火させない
    if (deckPeekState && deckPeekState.pendingUid) { deckPeekState.pendingUid = null; renderDeckPeekOverlay(); }
    if (partnerRemoveState && partnerRemoveState.pendingUid) { partnerRemoveState.pendingUid = null; renderPartnerRemoveOverlay(); }
    if (actionState && actionState.pendingUid) { actionState.pendingUid = null; renderActionGuardOverlay(); }
  });

  // ---- 現場のキャラ／パートナーをクリックした時のメニュー(今は「推理」のみだが、
  // 今後アクション等が増える想定でメニュー形式にしている) ----
  let openCardMenuKey = null; // `${side}:${targetType}:${uid}`
  function cardMenuKey(side, targetType, uid){ return `${side}:${targetType}:${uid}`; }
  function toggleCardMenu(side, targetType, uid){
    if (choiceState || replayMode || mulliganPhase || actionState || apBuffState || misleadState || handDiscardState || bonusEvidenceState || sleepForOppDiscardState || sleepCostState || lpBuffChoiceState || contactState || oppHandPickState || freePlayChoiceState || actionEndSwapState || kaitoActionEndState || keywordGrantChoiceState || evidencePickState || switchState || hiramekiState || hiramekiSleepState || mrReplaceState) return;
    const key = cardMenuKey(side, targetType, uid);
    openCardMenuKey = openCardMenuKey === key ? null : key;
    renderBoard(match);
  }
  function closeCardMenu(){
    if (openCardMenuKey === null) return;
    openCardMenuKey = null;
    renderBoard(match);
  }
  function cardActionMenuHtml(side, targetType, uid, lp){
    if (targetType === 'hand') {
      const check = canPlayHandCard(side, uid);
      const cardDef = CARD_BY_ID.get(uidToCardId(uid));
      const label = cardDef && cardDef.card_type === 'イベント' ? '使用する' : '登場させる';
      const handSetEffect = getHandSetDeclare(uidToCardId(uid));
      const handSetBtnHtml = handSetEffect ? (() => {
        const declareCheck = canDeclareHandSet(side, uid);
        return `<button${declareCheck.ok ? '' : ' disabled title="' + declareCheck.reason + '"'} onclick="closeCardMenu(); declareHandSet('${side}', '${uid}');">宣言：手札から「${handSetEffect.hostName}」にセットする</button>`;
      })() : '';
      const handDeclareEffect = getHandDeclareReplaceEffect(uidToCardId(uid));
      const handDeclareBtnHtml = handDeclareEffect ? (() => {
        const declareCheck = canDeclareFromHand(side, uid);
        return `<button${declareCheck.ok ? '' : ' disabled title="' + declareCheck.reason + '"'} onclick="closeCardMenu(); declareFromHand('${side}', '${uid}');">宣言：【${handDeclareEffect.costColor}】をリムーブして登場</button>`;
      })() : '';
      return `
        <div class="deck-menu card-action-menu" onclick="event.stopPropagation()">
          <button${check.ok ? '' : ' disabled title="' + check.reason + '"'} onclick="closeCardMenu(); playCard('${side}', '${uid}');">${label}</button>
          ${check.ok ? '' : `<div class="card-action-reason">${check.reason}</div>`}
          ${handDeclareBtnHtml}
          ${handSetBtnHtml}
        </div>
      `;
    }
    if (targetType === 'partner') {
      const assistCheck = canUseAssist(side);
      const reasonCheck = canUseReason(side, targetType, uid);
      const solveCheck = canSolveCase(side);
      return `
        <div class="deck-menu card-action-menu" onclick="event.stopPropagation()">
          <button${reasonCheck.ok ? '' : ' disabled title="' + reasonCheck.reason + '"'} onclick="closeCardMenu(); performReason('${side}', '${targetType}', '${uid}');">推理（証拠+${lp}）</button>
          <button${assistCheck.ok ? '' : ' disabled title="' + assistCheck.reason + '"'} onclick="closeCardMenu(); performAssist('${side}');">アシスト</button>
          <button${solveCheck.ok ? '' : ' disabled title="' + solveCheck.reason + '"'} onclick="closeCardMenu(); performSolveCase('${side}');">事件解決</button>
          ${romanceDeclareButtonsHtml(side, uid)}
        </div>
      `;
    }
    if (targetType === 'case') {
      const caseDeclareEffect = getCaseFaceUpRevealDeclareEffect(uidToCardId(uid));
      const romanceCaseBtnHtml = getCaseRomanceDeclare(uidToCardId(uid)) ? (() => {
        const declareCheck = canDeclareCaseRomance(side);
        return `<button${declareCheck.ok ? '' : ' disabled title="' + declareCheck.reason + '"'} onclick="closeCardMenu(); declareCaseRomance('${side}');">宣言：証拠を2つ表向き→回収／使用</button>`;
      })() : '';
      const caseDeclareBtnHtml = caseDeclareEffect ? (() => {
        const declareCheck = canDeclareCaseFaceUpReveal(side);
        return `<button${declareCheck.ok ? '' : ' disabled title="' + declareCheck.reason + '"'} onclick="closeCardMenu(); declareCaseFaceUpReveal('${side}');">宣言：裏向きの証拠を${caseDeclareEffect.faceUpCount}つ表向きにする</button>`;
      })() : '';
      const traceCaseBtnHtml = getCaseTraceDeclare(uidToCardId(uid)) ? (() => {
        const declareCheck = canDeclareCaseTrace(side);
        return `<button${declareCheck.ok ? '' : ' disabled title="' + declareCheck.reason + '"'} onclick="closeCardMenu(); declareCaseTrace('${side}');">宣言：証拠を表向き→効果を選ぶ</button>`;
      })() : '';
      const kissCaseBtnHtml = getCaseKissDeclare(uidToCardId(uid)) ? (() => {
        const declareCheck = canDeclareCaseKiss(side);
        return `<button${declareCheck.ok ? '' : ' disabled title="' + declareCheck.reason + '"'} onclick="closeCardMenu(); declareCaseKiss('${side}');">宣言：証拠を2つ表向き→効果を与える</button>`;
      })() : '';
      const genericCaseEntry = getGenericCaseDeclare(uidToCardId(uid));
      const genericCaseBtnHtml = genericCaseEntry ? (() => {
        const declareCheck = canDeclareGenericCase(side);
        return `<button${declareCheck.ok ? '' : ' disabled title="' + declareCheck.reason + '"'} onclick="closeCardMenu(); declareGenericCase('${side}');">${genericCaseEntry.def.label(genericCaseEntry.params)}</button>`;
      })() : '';
      return `
        <div class="deck-menu card-action-menu" onclick="event.stopPropagation()">
          ${caseDeclareBtnHtml}
          ${romanceCaseBtnHtml}
          ${traceCaseBtnHtml}
          ${kissCaseBtnHtml}
          ${genericCaseBtnHtml}
        </div>
      `;
    }
    if (targetType === 'field') {
      const actionCheck = canUseAction(side, uid);
      const reasonCheck = canUseReason(side, targetType, uid);
      const declareEffect = getDeclareApBuffEffect(uidToCardId(uid));
      const declareBtnHtml = declareEffect ? (() => {
        const declareCheck = canDeclareApBuff(side, uid);
        return `<button${declareCheck.ok ? '' : ' disabled title="' + declareCheck.reason + '"'} onclick="closeCardMenu(); declareApBuff('${side}', '${uid}');">宣言：AP＋${declareEffect.amount}</button>`;
      })() : '';
      const sleepOtherEffect = getSleepOtherDeclareEffect(uidToCardId(uid));
      const sleepOtherBtnHtml = sleepOtherEffect ? (() => {
        const declareCheck = canDeclareSleepOther(side, uid);
        return `<button${declareCheck.ok ? '' : ' disabled title="' + declareCheck.reason + '"'} onclick="closeCardMenu(); declareSleepOther('${side}', '${uid}');">宣言：ドロー＋LP＋${sleepOtherEffect.lpAmount}</button>`;
      })() : '';
      const removeEventEffect = getRemoveEventEffect(uidToCardId(uid));
      const removeEventBtnHtml = removeEventEffect ? (() => {
        const declareCheck = canDeclareRemoveEvent(side, uid);
        return `<button${declareCheck.ok ? '' : ' disabled title="' + declareCheck.reason + '"'} onclick="closeCardMenu(); declareRemoveEvent('${side}', '${uid}');">宣言：リムーブして回収</button>`;
      })() : '';
      const deckBottomEffect = getSelfToDeckBottomDeclareEffect(uidToCardId(uid));
      const deckBottomBtnHtml = deckBottomEffect ? (() => {
        const declareCheck = canDeclareSelfToDeckBottom(side, uid);
        return `<button${declareCheck.ok ? '' : ' disabled title="' + declareCheck.reason + '"'} onclick="closeCardMenu(); declareSelfToDeckBottom('${side}', '${uid}');">宣言：デッキ下へ＋LP＋${deckBottomEffect.lpAmount}</button>`;
      })() : '';
      const freePlayEffect = getFreePlayGrantChargeEffect(uidToCardId(uid));
      const freePlayBtnHtml = freePlayEffect ? (() => {
        const declareCheck = canDeclareFreePlayGrantCharge(side, uid);
        return `<button${declareCheck.ok ? '' : ' disabled title="' + declareCheck.reason + '"'} onclick="closeCardMenu(); declareFreePlayGrantCharge('${side}', '${uid}');">宣言：デッキ下へ＋無料登場</button>`;
      })() : '';
      return `
        <div class="deck-menu card-action-menu" onclick="event.stopPropagation()">
          <button${reasonCheck.ok ? '' : ' disabled title="' + reasonCheck.reason + '"'} onclick="closeCardMenu(); performReason('${side}', '${targetType}', '${uid}');">推理（証拠+${lp}）</button>
          <button${actionCheck.ok ? '' : ' disabled title="' + actionCheck.reason + '"'} onclick="closeCardMenu(); startAction('${side}', '${uid}');">アクション</button>
          ${declareBtnHtml}
          ${sleepOtherBtnHtml}
          ${removeEventBtnHtml}
          ${deckBottomBtnHtml}
          ${freePlayBtnHtml}
          ${romanceDeclareButtonsHtml(side, uid)}
        </div>
      `;
    }
    return `
      <div class="deck-menu card-action-menu" onclick="event.stopPropagation()">
        <button onclick="closeCardMenu(); performReason('${side}', '${targetType}', '${uid}');">推理（証拠+${lp}）</button>
      </div>
    `;
  }

  // FILEエリアの積み重ね表示(盤面デザイン見本のFILEスタックと同じ考え方: 横向きの
  // カード裏面を、最大想定枚数(10枚)がちょうどコンテナ内に収まる間隔で重ねて並べる)
  const STACK_MAX = 10;
  // assistCardId を渡すと、アシスト中のパートナーをFILEの一番上(最後尾)に
  // 実際の顔が見える形で積み増して表示する
  function renderFileStack(container, count, assistCardId){
    container.innerHTML = '';
    const totalCount = count + (assistCardId ? 1 : 0);
    if (totalCount === 0) return;
    // getBoundingClientRect()は盤面全体の90度回転で幅/高さが入れ替わった「見た目」の
    // 値を返すため、レイアウト上の実サイズであるclientWidthを使う
    const containerWidth = container.clientWidth;
    const cardW = 162; // 横向き(他のカードと同じ162x116)
    const step = Math.min(cardW, (containerWidth - cardW) / Math.max(1, STACK_MAX - 1));
    for (let i = 0; i < count; i++) {
      const div = document.createElement('div');
      div.className = 'file-card-back';
      div.style.left = (i * step) + 'px';
      div.style.width = cardW + 'px';
      div.style.zIndex = String(i);
      div.innerHTML = '<div class="back-img"></div>';
      container.appendChild(div);
    }
    if (assistCardId) {
      const div = document.createElement('div');
      div.className = 'file-card-back assist-file-card';
      div.style.left = (count * step) + 'px';
      div.style.width = cardW + 'px';
      div.style.zIndex = String(count);
      div.title = `${cardName(assistCardId)}（アシスト中）`;
      div.innerHTML = `<div class="assist-face"><img src="${cardImage(assistCardId)}" alt="${cardName(assistCardId)}"></div>`;
      container.appendChild(div);
    }
  }

  // 証拠エリアの積み重ね表示(FILEスタックと同じ考え方だが、縦長のコンテナなので
  // 横向きのカードを上から下へ均等な間隔で重ねて並べる)
  function renderEvidenceStack(container, sideKey, evidenceArr){
    container.innerHTML = '';
    const count = evidenceArr.length;
    if (count === 0) return;
    const containerHeight = container.clientHeight;
    const cardH = 116; // 他のカードと同じ162x116(横向き)
    const step = Math.min(cardH, (containerHeight - cardH) / Math.max(1, STACK_MAX - 1));
    evidenceArr.forEach((card, i) => {
      const div = document.createElement('div');
      const isPickable = !!evidencePickState && evidencePickState.side === sideKey
        && ((evidencePickState.mode === 'toHand' || evidencePickState.mode === 'toDeckBottom') ? true : evidencePickState.mode === 'toFaceDown' ? !!card.faceUp : !card.faceUp);
      const isSelected = isPickable && evidencePickState.selectedUids.includes(card.uid);
      div.className = 'evi-card-back' + (card.faceUp ? ' face-up' : '') + (isPickable ? ' action-pickable' : '') + (isSelected ? ' mislead-selected' : '');
      div.style.top = (i * step) + 'px';
      div.style.zIndex = String(i);
      div.innerHTML = card.faceUp
        ? `<div class="evi-face"><img src="${cardImage(card.cardId)}" alt="${cardName(card.cardId)}"></div>`
        : '<div class="back-img"></div>';
      if (isPickable) {
        div.title = evidencePickState.mode === 'toHand' ? `「${cardName(card.cardId)}」を手札に加える`
          : evidencePickState.mode === 'toDeckBottom' ? `「${cardName(card.cardId)}」をデッキの下に移す`
          : `「${cardName(card.cardId)}」を${evidencePickState.mode === 'toFaceDown' ? '裏' : '表'}向きにする`;
        div.onclick = (e) => { e.stopPropagation(); toggleEvidencePick(card.uid); };
      }
      container.appendChild(div);
    });
  }

  // 現場のキャラカードの状態(スリープ/クリック挙動/メニュー)を既存のDOM要素に反映する。
  // アクティブ⇔スリープの切り替え時にCSSトランジションで縦横がゆっくり回転して見えるよう、
  // 要素そのものは使い回し、クラスやonclickだけを更新する(要素を作り直すとアニメーションしない)
  function applyFieldCardState(div, wrap, instance, sideKey){
    div.classList.toggle('sleeping', !!instance.sleeping);
    div.classList.toggle('stunned', !!instance.stunned);
    // 〚ブレット〛(このキャラのアクションはガードできない)を持っている間だけ、
    // 周囲を赤くして一目で分かるようにする(常時／一時付与どちらも対象)
    div.classList.toggle('bullet', charHasKeyword(instance, 'ブレット'));
    // 変装等でuidはそのままcardIdだけが変わることがあるため、画像も必ず現在のcardIdに
    // 合わせて更新する(既存のDOM要素を使い回す都合上、放っておくと変装前の絵のまま残る)
    const img = div.querySelector('.card-face img');
    if (img) {
      const expectedSrc = cardImage(instance.cardId);
      if (img.dataset.cardId !== String(instance.cardId)) {
        img.src = expectedSrc;
        img.alt = cardName(instance.cardId);
        img.dataset.cardId = String(instance.cardId);
      }
    }
    // 重なっている/セットされているカードを、キャラの後ろに少しずつずらして表示する
    // (キャラ本体は動かさない。枚数や中身が変わったときだけ作り直す)
    const underKey = (instance.under || []).map(u => u.uid + ':' + u.cardId).join(',');
    if (div.dataset.underKey !== underKey) {
      div.dataset.underKey = underKey;
      div.querySelectorAll('.under-card').forEach(el => el.remove());
      (instance.under || []).forEach((u, i) => {
        const el = document.createElement('div');
        el.className = 'under-card';
        const shift = 20 * (i + 1);
        el.style.transform = `translate(calc(-50% - ${shift}px), calc(-50% + ${Math.min(shift / 2, 10)}px))`;
        el.innerHTML = `<img src="${cardImage(u.cardId)}" alt="${cardName(u.cardId)}">`;
        el.title = `「${cardName(u.cardId)}」が下に重なっています`;
        div.insertBefore(el, div.firstChild);
      });
    }
    const c = defOfInst(instance);
    const lp = effectiveLp(match, instance);
    div.title = instance.stunned ? `${cardName(instance.cardId)}（スタン中）`
      : instance.sleeping ? `${cardName(instance.cardId)}（スリープ中）` : cardName(instance.cardId);
    // スタン状態：次のオートフェイズでアクティブにならず、代わりにスリープになる。
    // .card-face(スリープ時に自分自身がさらに-90度回転する)の外、.char-card直下に置き、
    // num-badgeと同じく盤面全体の回転だけを打ち消せば正しい向きになるようにする
    // スタンはバッジではなく、カードを180度回した向きで表す(.stunnedのCSS)。古いバッジが残っていれば消す
    { const oldBadge = div.querySelector('.stun-badge'); if (oldBadge) oldBadge.remove(); }
    // LPが東尾マリア等の一時バフで元の値から変わっているときだけ、現場でも
    // 分かるようにバッジで表示する(推理メニューのLP表示と同じeffectiveLpを使う)
    const baseLp = c && c.lp != null ? c.lp : 0;
    let lpBadge = div.querySelector('.lp-badge');
    if (lp !== baseLp) {
      if (!lpBadge) {
        lpBadge = document.createElement('div');
        lpBadge.className = 'lp-badge';
        div.appendChild(lpBadge);
      }
      lpBadge.textContent = `LP${lp}`;
    } else if (lpBadge) {
      lpBadge.remove();
    }

    // アクションの対象選択中は、相手の現場のカードを直接クリックして選べるようにする
    // (ガードは相手が選ぶダイアログ形式のまま。その間は他の現場カードの通常メニューは開けない)
    // 中森銀三等：「このキャラは相手の現場にいるアクティブ状態のキャラを指定してアクション
    // できる」を一時的に持つ場合、アクティブ状態の相手キャラも対象にできる(〚キーワード〛と
    // 同じtempKeywords付与の仕組みを流用する)
    const actionActor = actionState ? findActorAnywhere(actionState.side, actionState.actorUid) : null;
    const actionActorCanTargetActive = canTargetActiveEnemies(actionActor);
    const forcedActionTargetUid = actionState && actionState.step === 'target' ? getForcedActionTargetUid() : null;
    const isActionTarget = actionState && actionState.step === 'target' && sideKey === actionState.oppSide
      && (instance.sleeping || actionActorCanTargetActive || canTargetSetBearingActiveEnemy(actionActor, instance))
      && !isProtectedByLowLevelGuard(sideKey, c) && !hasActionLockRestriction(c) && !isImmuneWhileSleepingFromAction(c, instance)
      && (!forcedActionTargetUid || instance.uid === forcedActionTargetUid);
    // 「キャラを1枚まで選び、ターン終了時までAP＋Nする」：自分・相手どちらの現場の
    // キャラも(状態を問わず)直接クリックで選べる
    const isApBuffTarget = !!apBuffState && (!apBuffState.colorRestrict || cardHasColor(c, apBuffState.colorRestrict))
      && (!apBuffState.trait || cardHasTrait(c, apBuffState.trait))
      && !isUntargetableBy(sideKey, instance, apBuffState.side)
      && (!apBuffState.excludeSelf || instance.uid !== apBuffState.sourceUid);
    // ミスリード：相手の推理に対して、自分の現場のアクティブ状態のミスリード持ちキャラを
    // 選ぶ(複数選択可。選ぶたびにトグルする)
    const misleadValue = getMisleadValue(instance.cardId);
    const isMisleadTarget = !!misleadState && sideKey === misleadState.oppSide && !instance.sleeping && misleadValue != null;
    const misleadSelected = isMisleadTarget && misleadState.selectedUids.includes(instance.uid);
    // 【宣言】コスト〚このキャラ以外のキャラを1枚スリープさせる〛：宣言した本人以外の
    // アクティブなキャラを、自分・相手どちらの現場からでも直接クリックで選べる
    const isSleepCostTarget = !!sleepCostState && !instance.sleeping && instance.uid !== sleepCostState.sourceUid;
    // 東尾マリア等：自分の現場にいる、LP◯以下かつ指定のカード名のキャラだけ選べる
    const isLpBuffTarget = !!lpBuffChoiceState && sideKey === lpBuffChoiceState.side && instance.uid !== lpBuffChoiceState.sourceUid
      && c && c.lp != null && c.lp <= lpBuffChoiceState.lpMaxFilter && c.name === lpBuffChoiceState.nameFilter;
    // ミステリーコースター等：自分・相手どちらの現場のキャラも、状態を問わず選んで
    // ターン終了時までキーワードを付与できる
    const isKeywordGrantTarget = !!keywordGrantChoiceState;
    // スイッチ：現場が5枚埋まっている状態で新しいキャラを出すとき、リムーブする1枚を
    // 自分の現場から状態を問わず選ぶ
    const isSwitchTarget = !!switchState && sideKey === switchState.side;
    // ヒラメキ「キャラを1枚まで選び、スリープさせる」：自分・相手どちらの現場の
    // アクティブなキャラも選べる
    const isHiramekiSleepTarget = !!hiramekiSleepState && !instance.sleeping
      && (hiramekiSleepState.apLimit == null || effectiveAp(match, instance, sideKey) <= hiramekiSleepState.apLimit);
    // MRの入れ替え：新しく登場したMRと、既に現場にいたMR(パートナーエリアの場合は別枠で
    // 処理する)のうち、リムーブする方を直接クリックして選ぶ
    const isMrReplaceTarget = !!mrReplaceState && sideKey === mrReplaceState.side
      && (instance.uid === mrReplaceState.uid || instance.uid === mrReplaceState.otherUid);
    div.classList.toggle('action-pickable', !!isActionTarget || isApBuffTarget || isMisleadTarget || isSleepCostTarget || isLpBuffTarget || isKeywordGrantTarget || isSwitchTarget || isHiramekiSleepTarget || isMrReplaceTarget);
    div.classList.toggle('mislead-selected', !!misleadSelected);
    if (isMrReplaceTarget) {
      div.title = `「${cardName(instance.cardId)}」をリムーブする`;
      div.onclick = (e) => { e.stopPropagation(); selectMrReplaceTarget(instance.uid); };
    } else if (isHiramekiSleepTarget) {
      div.title = `「${cardName(instance.cardId)}」をスリープさせる`;
      div.onclick = (e) => { e.stopPropagation(); selectHiramekiSleepTarget(sideKey, instance.uid); };
    } else if (isSwitchTarget) {
      div.title = `「${cardName(instance.cardId)}」をリムーブして入れ替える（スイッチ）`;
      div.onclick = (e) => { e.stopPropagation(); selectSwitchTarget(instance.uid); };
    } else if (isKeywordGrantTarget) {
      div.title = `「${cardName(instance.cardId)}」にターン終了時まで〚${keywordGrantChoiceState.keyword}〛を与える`;
      div.onclick = (e) => { e.stopPropagation(); selectKeywordGrantTarget(instance.uid); };
    } else if (isLpBuffTarget) {
      div.title = `「${cardName(instance.cardId)}」をターン終了時までLP＋${lpBuffChoiceState.amount}する`;
      div.onclick = (e) => { e.stopPropagation(); selectLpBuffTarget(instance.uid); };
    } else if (isSleepCostTarget) {
      div.title = `「${cardName(instance.cardId)}」をスリープさせる（コスト）`;
      div.onclick = (e) => { e.stopPropagation(); selectSleepCostTarget(sideKey, instance.uid); };
    } else if (isMisleadTarget) {
      div.title = `「${cardName(instance.cardId)}」でミスリード（LP－${misleadValue}）${misleadSelected ? '（選択中）' : ''}`;
      div.onclick = (e) => { e.stopPropagation(); toggleMisleadSelect(instance.uid); };
    } else if (isApBuffTarget) {
      div.title = `「${cardName(instance.cardId)}」をターン終了時までAP＋${apBuffState.amount}する`;
      div.onclick = (e) => { e.stopPropagation(); selectApBuffTarget(instance.uid); };
    } else if (isActionTarget) {
      div.title = `「${cardName(instance.cardId)}」を対象にする`;
      div.onclick = (e) => { e.stopPropagation(); selectActionTarget(instance.uid); };
    } else if (!actionState && !replayMode && !misleadState && !sleepCostState && !lpBuffChoiceState && !contactState && !keywordGrantChoiceState && !evidencePickState && !switchState && !hiramekiState && !hiramekiSleepState && !mrReplaceState) {
      // スリープ中でもメニュー自体は開ける(推理・アクションは使えないが、【宣言】能力は
      // コストに「スリープさせる」が無い限りスリープ状態でも使用できるため)
      div.onclick = (e) => { e.stopPropagation(); toggleCardMenu(sideKey, 'field', instance.uid); };
    } else {
      div.onclick = null;
    }

    const menuEl = wrap.querySelector('.card-action-menu');
    const shouldShowMenu = !actionState && !isApBuffTarget && !misleadState && !sleepCostState && !lpBuffChoiceState && !contactState && !keywordGrantChoiceState && !evidencePickState && !switchState && !hiramekiState && !hiramekiSleepState && !mrReplaceState && openCardMenuKey === cardMenuKey(sideKey, 'field', instance.uid);
    if (shouldShowMenu) {
      const html = cardActionMenuHtml(sideKey, 'field', instance.uid, lp);
      if (menuEl) menuEl.outerHTML = html; else wrap.insertAdjacentHTML('beforeend', html);
    } else if (menuEl) {
      menuEl.remove();
    }
  }

  // 現場のキャラカード(盤面デザイン見本のchar-card)。新規に現場へ登場したときだけ呼ばれる
  function renderFieldCard(instance, sideKey){
    const wrap = document.createElement('div');
    wrap.className = 'card-menu-wrap';
    const div = document.createElement('div');
    div.className = 'char-card';
    div.dataset.uid = instance.uid;
    div.innerHTML = `<div class="card-face"><img src="${cardImage(instance.cardId)}" alt="${cardName(instance.cardId)}"></div>`;
    wrap.appendChild(div);
    applyFieldCardState(div, wrap, instance, sideKey);
    return wrap;
  }

  // 現場の並び(uidの並び)が変わっていない場合は既存のDOM要素をそのまま使い回して
  // 状態だけ更新する。並びが変わった(登場/リムーブがあった)場合のみ作り直す
  function renderFieldRow(fieldRow, fieldList, sideKey){
    const existingWraps = Array.from(fieldRow.children);
    const existingUids = existingWraps.map(w => w.querySelector('.char-card')?.dataset.uid);
    const newUids = fieldList.map(c => c.uid);
    const sameSet = existingUids.length === newUids.length && existingUids.every((u, i) => u === newUids[i]);
    if (sameSet) {
      fieldList.forEach((instance, i) => applyFieldCardState(existingWraps[i].querySelector('.char-card'), existingWraps[i], instance, sideKey));
    } else {
      fieldRow.innerHTML = '';
      fieldList.forEach(c => fieldRow.appendChild(renderFieldCard(c, sideKey)));
    }
  }

  // 手札のカード(盤面デザイン見本のhcard face)。クリックすると「登場させる」等の
  // メニューを表示する(推理などと同じメニュー形式。今後アクションが増える想定)
  function renderHandCard(instance, sideKey, index, total){
    const wrap = document.createElement('div');
    wrap.className = 'card-menu-wrap';
    const div = document.createElement('div');
    div.className = 'hcard';
    div.dataset.uid = instance.uid;
    const mid = (total - 1) / 2;
    const offset = index - mid;
    const rotate = offset * 9;
    const lift = Math.abs(offset) * 12;
    // 自分側・相手側で扇の反り方・重なる順番とも完全に同じ計算にする。相手側の
    // ゾーン全体には親要素(.rotate180)で180度回転がかかっているので、それだけで
    // 自分側を上下左右反転させた自然な見た目になる
    div.style.transform = `rotate(${rotate}deg) translateY(${lift}px)`;
    div.style.zIndex = String(index + 1);
    div.innerHTML = `
      <img src="${cardImage(instance.cardId)}" alt="${cardName(instance.cardId)}">
    `;
    div.title = cardName(instance.cardId);

    // 登場時効果などで「手札から1枚選んでリムーブ」が必要な間や、ネクストヒントで
    // 手札から1枚使用できる間は、手札のカードを直接クリックして選べるようにする
    // (ダイアログではなく実際の手札から選ぶため)
    const isDeckPeekHandPick = deckPeekState && deckPeekState.step === 'remove' && sideKey === deckPeekState.side;
    const isPartnerRemoveHandPick = partnerRemoveState && partnerRemoveState.step === 'hand' && sideKey === partnerRemoveState.side;
    const isHandDiscardPick = handDiscardState && sideKey === handDiscardState.side;
    const isBonusEvidencePick = bonusEvidenceState && sideKey === bonusEvidenceState.side;
    // 変装への反応(disguiseReactState)が開いている間は、通常のコンタクトの
    // キューがまだ残っていても一旦中断されているので、カットイン／変装の選択肢を
    // 出さない(手札を捨てようとして誤ってカットインが発動してしまうのを防ぐ)
    const isCutInPick = !disguiseReactState && contactState && contactState.queue[0] === sideKey && contactState.cutinBlockedSide !== sideKey && hasCutInAbility(instance.cardId, sideKey);
    const isDisguisePick = !disguiseReactState && contactState && contactState.queue[0] === sideKey && canUseDisguise(sideKey, instance.uid);
    const isDisguiseReactPick = !!disguiseReactState && sideKey === disguiseReactState.oppSide;
    const cInst = defOfInst(instance);
    const isOppHandPick = !!oppHandPickState && sideKey === oppHandPickState.oppSide
      && cInst && cInst.level != null && cInst.level <= oppHandPickState.levelLimit;
    const isFreePlayPick = !!freePlayChoiceState && sideKey === freePlayChoiceState.side
      && cInst && cInst.card_type === 'キャラ' && cInst.level != null && cInst.level <= freePlayChoiceState.levelMax
      && (!freePlayChoiceState.color || cardHasColor(cInst, freePlayChoiceState.color));
    const isActionEndSwapPick = (!!actionEndSwapState && sideKey === actionEndSwapState.side
      && cInst && cInst.card_type === 'キャラ' && cInst.level != null && cInst.level <= actionEndSwapState.levelMax
      && actionEndSwapMatch(actionEndSwapState, cInst))
      || (!!kaitoActionEndState && sideKey === kaitoActionEndState.side
      && cInst && cInst.card_type === 'キャラ' && cInst.level != null && cInst.level <= kaitoActionEndState.levelMax
      && cardHasColor(cInst, kaitoActionEndState.color) && !nameIs(cInst, kaitoActionEndState.excludeName));
    const isNextHintPick = !!(match.turn && match.turn.nextHintPending && sideKey === match.turn.activeSide);
    const nextHintCheck = isNextHintPick ? canPlayHandCard(sideKey, instance.uid) : null;
    if (isDeckPeekHandPick || isPartnerRemoveHandPick || isHandDiscardPick || isBonusEvidencePick || isCutInPick || isDisguisePick || isDisguiseReactPick || isOppHandPick || isFreePlayPick || isActionEndSwapPick) {
      div.classList.add('action-pickable');
      if (isCutInPick || isDisguisePick) div.classList.add('cutin-glow');
      div.title = isCutInPick ? `「${cardName(instance.cardId)}」でカットインする`
        : isDisguisePick ? `「${cardName(instance.cardId)}」に変装する`
        : isDisguiseReactPick ? `「${cardName(instance.cardId)}」をリムーブする（変装への反応）`
        : (isFreePlayPick || isActionEndSwapPick) ? `「${cardName(instance.cardId)}」を登場させる`
        : `「${cardName(instance.cardId)}」をリムーブする`;
      // CSSの:hoverだと隣のカードと重なって反応が不安定なことがあるため、
      // JSでマウスの出入りを直接検知してハイライト用クラスを切り替える
      div.addEventListener('mouseenter', () => div.classList.add('hover-glow'));
      div.addEventListener('mouseleave', () => div.classList.remove('hover-glow'));
      div.onclick = (e) => {
        e.stopPropagation();
        if (isDeckPeekHandPick) confirmDeckPeekRemove(instance.uid);
        else if (isPartnerRemoveHandPick) selectPartnerRemoveHand(instance.uid);
        else if (isHandDiscardPick) selectHandDiscardTarget(instance.uid);
        else if (isBonusEvidencePick) selectBonusEvidenceHand(instance.uid);
        else if (isCutInPick) contactUseCutIn(sideKey, instance.uid);
        else if (isDisguisePick) contactUseDisguise(sideKey, instance.uid);
        else if (isDisguiseReactPick) selectDisguiseReactDiscard(instance.uid);
        else if (isOppHandPick) selectOppHandPick(instance.uid);
        else if (isFreePlayPick) selectFreePlayChoice(instance.uid);
        else selectActionEndSwapHand(instance.uid);
      };
    } else if (isNextHintPick) {
      // ネクストヒントで加わったカードも、他の手札と同じくクリックしたら
      // メニューを開いて「登場させる」ボタンから使う(即プレイはしない)
      if (nextHintCheck.ok) div.classList.add('action-pickable');
      const nextHintVerb = cInst && cInst.card_type === 'イベント' ? '使用する' : '登場させる';
      div.title = nextHintCheck.ok ? `「${cardName(instance.cardId)}」を${nextHintVerb}` : `${cardName(instance.cardId)}（${nextHintCheck.reason}）`;
      div.addEventListener('mouseenter', () => div.classList.add('hover-glow'));
      div.addEventListener('mouseleave', () => div.classList.remove('hover-glow'));
      div.onclick = (e) => { e.stopPropagation(); toggleCardMenu(sideKey, 'hand', instance.uid); };
    } else if (!replayMode && !deckPeekState && !partnerRemoveState && !handDiscardState && !bonusEvidenceState && !sleepForOppDiscardState && !contactState && !oppHandPickState && !freePlayChoiceState && !actionEndSwapState && !kaitoActionEndState && !evidencePickState && !switchState && !hiramekiState && !hiramekiSleepState) {
      div.onclick = (e) => { e.stopPropagation(); toggleCardMenu(sideKey, 'hand', instance.uid); };
    }

    wrap.appendChild(div);
    if (!deckPeekState && !partnerRemoveState && !handDiscardState && !bonusEvidenceState && !sleepForOppDiscardState && !contactState && !oppHandPickState && !freePlayChoiceState && !actionEndSwapState && !kaitoActionEndState && !evidencePickState && !switchState && !hiramekiState && !hiramekiSleepState && openCardMenuKey === cardMenuKey(sideKey, 'hand', instance.uid)) {
      wrap.insertAdjacentHTML('beforeend', cardActionMenuHtml(sideKey, 'hand', instance.uid));
    }
    return wrap;
  }

  function renderBoard(state){
    ['opponent', 'self'].forEach(sideKey => {
      const side = state[sideKey];
      const mirrored = sideKey === 'opponent';
      const zone = document.querySelector(`.zone[data-side="${sideKey}"]`);
      zone.querySelector('.deck-count').textContent = side.deckPile.length;
      const assisting = !!(side.partner && side.partner.assisting);
      zone.querySelector('.file-count').textContent = assisting ? `${side.file.length}+1` : side.file.length;
      renderFileStack(zone.querySelector('.file-stack'), side.file.length, assisting ? side.partner.cardId : null);
      zone.querySelector('.evidence-count').textContent = side.evidence.length;
      renderEvidenceStack(zone.querySelector('.evidence-stack'), sideKey, side.evidence);
      zone.querySelector('.remove-count').textContent = side.remove.length;
      const removeTop = zone.querySelector('.remove-top');
      // 新しいカードがこのリムーブエリアへ飛んでいる最中は、着地するまで「ひとつ前の
      // カード」を表示し続ける(このrenderBoard呼び出しが何度起きても、着地前なら
      // 常にこちらを優先する。これにより、連鎖する誘発効果で再描画が重なっても
      // 「移動中に消える」ことがなくなる)
      const pendingFlight = removeTopFlightPending[sideKey];
      const lastRemoved = pendingFlight !== null ? pendingFlight : side.remove[side.remove.length - 1];
      removeTop.style.display = lastRemoved ? '' : 'none';
      removeTop.innerHTML = lastRemoved
        ? `<img src="${cardImage(lastRemoved.cardId)}" alt="${cardName(lastRemoved.cardId)}">`
        : '';
      const removePileBtn = zone.querySelector('.remove-pile-btn');
      if (removePileBtn) removePileBtn.onclick = (e) => { e.stopPropagation(); toggleRemoveMenu(sideKey); };
      const removeMenuListBtn = zone.querySelector('.remove-menu-list');
      if (removeMenuListBtn) removeMenuListBtn.onclick = (e) => { e.stopPropagation(); closeRemoveMenu(); showRemoveList(sideKey); };
      const pileBtn = zone.querySelector('.deck-pile-btn');
      pileBtn.onclick = (e) => { e.stopPropagation(); toggleDeckMenu(sideKey); };
      const menuDrawBtn = zone.querySelector('.deck-menu-draw');
      menuDrawBtn.disabled = side.deckPile.length === 0;
      menuDrawBtn.onclick = (e) => { e.stopPropagation(); drawCard(sideKey); closeDeckMenu(); };
      const menuFileBtn = zone.querySelector('.deck-menu-file');
      menuFileBtn.disabled = side.deckPile.length === 0;
      menuFileBtn.onclick = (e) => { e.stopPropagation(); addToFile(sideKey); closeDeckMenu(); };
      const menuEvidenceBtn = zone.querySelector('.deck-menu-evidence');
      menuEvidenceBtn.disabled = side.deckPile.length === 0;
      menuEvidenceBtn.onclick = (e) => { e.stopPropagation(); addToEvidence(sideKey); closeDeckMenu(); };

      const fileStackEl = zone.querySelector('.file-stack');
      fileStackEl.onclick = (e) => { e.stopPropagation(); toggleFileMenu(sideKey); };
      const nextHintMenuBtn = zone.querySelector('.file-menu-nexthint');
      const nhCheck = canUseNextHint(sideKey);
      nextHintMenuBtn.disabled = !nhCheck.ok;
      nextHintMenuBtn.title = nhCheck.reason;
      nextHintMenuBtn.onclick = (e) => { e.stopPropagation(); startNextHint(sideKey); closeFileMenu(); };

      const caseSlot = zone.querySelector('.case-slot');
      const caseDeclareEffect = side.case ? getCaseFaceUpRevealDeclareEffect(side.case.cardId) : null;
      const caseMenuOpen = !!side.case && openCardMenuKey === cardMenuKey(sideKey, 'case', side.case.uid);
      const caseMenuHtml = caseMenuOpen ? cardActionMenuHtml(sideKey, 'case', side.case.uid) : '';
      // 事件編/解決編マーカー：先攻側は右下(後攻用の数字を隠す)、後攻側は左下(先攻用の数字を隠す)
      const isFirstPlayerSide = (match.firstPlayer || 'self') === sideKey;
      const caseMarkerHtml = side.case
        ? `<div class="case-marker ${isFirstPlayerSide ? 'corner-right' : 'corner-left'}">${side.case.resolved ? '解決編' : '事件編'}</div>`
        : '';
      caseSlot.innerHTML = side.case
        ? `<div class="art">${caseArtHtml(side.case.cardId)}</div>${caseMarkerHtml}${caseMenuHtml}`
        : `<div class="art">未選択</div>`;
      // アクション［事件］：対象選択中は、証拠が1つ以上ある相手の事件も直接クリックで選べる
      // (京極真(Lv7)等：「このキャラは事件を指定してアクションできない。」を持つ場合は対象にできない)
      const actorCannotTargetCase = !!(actionState && (CARD_BY_ID.get(uidToCardId(actionState.actorUid)) || {}).ability_text
        && CARD_BY_ID.get(uidToCardId(actionState.actorUid)).ability_text.includes('このキャラは事件を指定してアクションできない。'));
      const isCaseActionTarget = !!(actionState && actionState.step === 'target' && sideKey === actionState.oppSide
        && side.case && side.evidence.length > 0 && !actorCannotTargetCase && !getForcedActionTargetUid());
      caseSlot.classList.toggle('action-pickable', isCaseActionTarget);
      if (isCaseActionTarget) {
        caseSlot.title = `「${cardName(side.case.cardId)}」を対象にする`;
        caseSlot.onclick = (e) => { e.stopPropagation(); selectActionTarget(side.case.uid); };
      } else if ((caseDeclareEffect || (side.case && getCaseRomanceDeclare(side.case.cardId)) || (side.case && getCaseTraceDeclare(side.case.cardId)) || (side.case && getCaseKissDeclare(side.case.cardId)) || (side.case && getGenericCaseDeclare(side.case.cardId))) && !replayMode && !actionState && !apBuffState && !misleadState && !handDiscardState
          && !bonusEvidenceState && !sleepCostState && !lpBuffChoiceState && !contactState && !oppHandPickState
          && !freePlayChoiceState && !actionEndSwapState && !kaitoActionEndState && !keywordGrantChoiceState && !evidencePickState && !switchState && !hiramekiState && !hiramekiSleepState) {
        caseSlot.title = cardName(side.case.cardId);
        caseSlot.onclick = (e) => { e.stopPropagation(); toggleCardMenu(sideKey, 'case', side.case.uid); };
      } else {
        caseSlot.title = side.case ? cardName(side.case.cardId) : '';
        caseSlot.onclick = null;
      }
      // アクション［事件］の対象選択中は、事件カード本体だけでなく証拠の山を
      // クリックしても同じように選べるようにする(どちらでも反応する)
      const evidenceStackEl = zone.querySelector('.evidence-stack');
      if (isCaseActionTarget) {
        evidenceStackEl.classList.add('action-pickable');
        evidenceStackEl.title = `「${cardName(side.case.cardId)}」を対象にする`;
        evidenceStackEl.onclick = (e) => { e.stopPropagation(); selectActionTarget(side.case.uid); };
      } else if (!evidencePickState) {
        evidenceStackEl.classList.remove('action-pickable');
        evidenceStackEl.title = '';
        evidenceStackEl.onclick = null;
      }

      // パートナーエリアに移した〚特徴［ビッグジュエル］〛等のカード：パートナーカードの
      // 右隣を起点に、積んだ順に少しずつ右へずらして重ねて表示する(後から積んだカードほど
      // 右側・手前に見える)
      const jewelStackEl = zone.querySelector('.partner-jewel-stack');
      jewelStackEl.innerHTML = (side.partnerJewels || []).map((c, i) =>
        `<div class="jewel-card" data-uid="${c.uid}" style="left:${i * 28}px; z-index:${i + 1};" title="${cardName(c.cardId)}"><img src="${cardImage(c.cardId)}" alt="${cardName(c.cardId)}"></div>`
      ).join('');

      const partnerSlot = zone.querySelector('.partner-slot');
      partnerSlot.classList.toggle('sleeping', !!(side.partner && side.partner.sleeping));
      partnerSlot.classList.toggle('assisting', !!(side.partner && side.partner.assisting));
      partnerSlot.onclick = null;
      if (side.partner && side.partner.assisting) {
        // アシスト中はパートナーエリアから完全にいなくなり、空になる(枠も表示しない)
        partnerSlot.innerHTML = '';
        partnerSlot.title = `${cardName(side.partner.cardId)}（アシスト中：FILEエリアに移動）`;
      } else if (side.partner) {
        const pLp = effectiveLp(match, side.partner);
        // スリープ中でもメニューは開ける(推理・アシスト・事件解決は使えないが、
        // 【宣言】能力はコストに「スリープさせる」が無い限り使用できるため)
        const menuHtml = (openCardMenuKey === cardMenuKey(sideKey, 'partner', side.partner.uid))
          ? cardActionMenuHtml(sideKey, 'partner', side.partner.uid, pLp)
          : '';
        partnerSlot.innerHTML = `<img src="${cardImage(side.partner.cardId)}" alt="${cardName(side.partner.cardId)}">${menuHtml}`;
        partnerSlot.title = side.partner.sleeping ? `${cardName(side.partner.cardId)}（スリープ中）` : cardName(side.partner.cardId);
        if (!replayMode) {
          partnerSlot.onclick = (e) => { e.stopPropagation(); toggleCardMenu(sideKey, 'partner', side.partner.uid); };
        }
      } else {
        partnerSlot.innerHTML = '未選択';
        partnerSlot.title = '';
      }

      // パートナーエリアに移動したMR：推理・アクションはできないが、【宣言】能力や
      // パートナーエリアでも発動する能力は使用できる
      const partnerMRSlot = zone.querySelector('.partner-mr-slot');
      if (side.partnerMR) {
        partnerMRSlot.style.display = '';
        partnerMRSlot.classList.toggle('sleeping', !!side.partnerMR.sleeping);
        const mrUid = side.partnerMR.uid;
        // MRの入れ替え：パートナーエリアのMRが選択対象の場合、クリックでリムーブを選べる
        const isMrReplaceTarget = !!mrReplaceState && sideKey === mrReplaceState.side && mrReplaceState.otherIsPartner && mrUid === mrReplaceState.otherUid;
        partnerMRSlot.classList.toggle('action-pickable', isMrReplaceTarget);
        const menuOpen = !isMrReplaceTarget && openCardMenuKey === cardMenuKey(sideKey, 'partnerMR', mrUid);
        const menuHtml = menuOpen ? partnerMRMenuHtml(sideKey, mrUid) : '';
        partnerMRSlot.innerHTML = `<img src="${cardImage(side.partnerMR.cardId)}" alt="${cardName(side.partnerMR.cardId)}"><div class="mr-badge">MR</div>${menuHtml}`;
        if (isMrReplaceTarget) {
          partnerMRSlot.title = `「${cardName(side.partnerMR.cardId)}」をリムーブする`;
          partnerMRSlot.onclick = (e) => { e.stopPropagation(); selectMrReplaceTarget(mrUid); };
        } else {
          partnerMRSlot.title = `${cardName(side.partnerMR.cardId)}（パートナーエリア：推理・アクションは不可）`;
          partnerMRSlot.onclick = (replayMode || mrReplaceState) ? null : (e) => { e.stopPropagation(); toggleCardMenu(sideKey, 'partnerMR', mrUid); };
        }
      } else {
        partnerMRSlot.style.display = 'none';
        partnerMRSlot.innerHTML = '';
        partnerMRSlot.onclick = null;
      }

      const fieldRow = zone.querySelector('.field-row');
      renderFieldRow(fieldRow, side.field, sideKey);

      const handRow = zone.querySelector('.hand-row');
      handRow.innerHTML = mirrored ? '' : '<div class="hand-tray"></div>';
      side.hand.forEach((c, i) => handRow.appendChild(renderHandCard(c, sideKey, i, side.hand.length)));
    });
  }

  function describeEvent(ev){
    const sideLabel = (match[ev.side] && match[ev.side].deckName) || (ev.side === 'self' ? '自分' : '相手');
    if (ev.type === 'turnStart') return `── ターン${ev.turnNumber} 開始 ──`;
    if (ev.type === 'draw') return `${sideLabel}：デッキから1枚ドロー`;
    if (ev.type === 'addFile') return `${sideLabel}：デッキからFILEエリアに1枚追加`;
    if (ev.type === 'addEvidence') return `${sideLabel}：デッキから証拠エリアに1枚追加`;
    if (ev.type === 'evidenceFlip') return `${sideLabel}：証拠を1枚${ev.faceUp ? '表' : '裏'}向きにした`;
    if (ev.type === 'traitOverride') return `${sideLabel}：「${cardName(uidToCardId(ev.uid))}」の特徴が入れ替わった`;
    if (ev.type === 'tempTraitGrantAll') return `${sideLabel}：ターン終了時まで自分のすべてのエリアのキャラが〚特徴［${ev.trait}］〛を持つ`;
    if (ev.type === 'grantActionCaseKeyword') return `${sideLabel}：「${cardName(uidToCardId(ev.targetUid))}」にターン終了時まで、アクション［事件］時に手札を1枚リムーブして〚${ev.keyword}〛を得る効果を与えた`;
    if (ev.type === 'grantEndTask') return `${sideLabel}：「${cardName(ev.cardId)}」のターン終了時の効果を予約した`;
    if (ev.type === 'evidenceTopToRemove') return `${sideLabel}：自分の証拠を上から1つリムーブした`;
    if (ev.type === 'cutInEnterSleeping') return `${sideLabel}：【カットイン】で「${cardName(uidToCardId(ev.uid))}」をスリープ状態で登場させた`;
    if (ev.type === 'markEnteredByCutin') return `${sideLabel}：「${cardName(uidToCardId(ev.uid))}」が【カットイン】の効果で登場した`;
    if (ev.type === 'grantEndFileAdd') return `${sideLabel}：ターン終了時にデッキの上から${ev.n}枚をFILEエリアに置く予約`;
    if (ev.type === 'tempEndOfTurnBottomGrant') return `${sideLabel}：「${cardName(uidToCardId(ev.targetUid))}」にターン終了時にデッキの下へ移る効果を与えた`;
    if (ev.type === 'tempBaseLpOneGrant') return `${sideLabel}：「${cardName(uidToCardId(ev.targetUid))}」の元のLPがターン終了時まで1になった`;
    if (ev.type === 'removeToDeckTop') return `${sideLabel}：リムーブエリアのカードをデッキの上に移した`;
    if (ev.type === 'deckShuffle') return `${sideLabel}：デッキをシャッフルした`;
    if (ev.type === 'deckBottomToRemove') return `${sideLabel}：デッキの一番下のカードをリムーブエリアに移した`;
    if (ev.type === 'jewelToHand') return `${sideLabel}：パートナーエリアのカードを手札に加えた`;
    if (ev.type === 'fileTopFaceUp') return `${sideLabel}：FILEエリアの一番上のカードを表向きにした`;
    if (ev.type === 'tempNameGrant') return `${sideLabel}：「${cardName(uidToCardId(ev.uid))}」のカード名をターン終了時まで「${ev.name}」に書き換えた`;
    if (ev.type === 'handToUnder') return `${sideLabel}：手札のカードを「${cardName(uidToCardId(ev.hostUid))}」の下に重ねた`;
    if (ev.type === 'oppNoCutinDisguise') return `${sideLabel}：このターン中、相手は【カットイン】と【変装】を使用できない`;
    if (ev.type === 'grantGuardWhileSleeping') return `${sideLabel}：「${cardName(uidToCardId(ev.targetUid))}」に相手のターン終了時まで「スリープ状態でもガードできる」を与えた`;
    if (ev.type === 'grantForceTarget') return `${sideLabel}：「${cardName(uidToCardId(ev.uid || ev.targetUid))}」が相手のターン終了時まで必ず指定される`;
    if (ev.type === 'handToDeckTop') return `${sideLabel}：手札を1枚デッキの上に移した`;
    if (ev.type === 'handToFileBottom') return `${sideLabel}：手札を1枚FILEエリアの一番下に表向きで移した`;
    if (ev.type === 'evidenceToDeckBottom') return `${sideLabel}：証拠を1枚デッキの下に移した`;
    if (ev.type === 'partnerMRToField') return `${sideLabel}：パートナーエリアのキャラを現場に登場させた`;
    if (ev.type === 'underToEvidenceFaceUp') return `${sideLabel}：セットされていたカードを表向きで証拠として得た`;
    if (ev.type === 'deckBottomToHand') return `${sideLabel}：デッキの下から1枚を手札に加えた`;
    if (ev.type === 'fieldToEvidenceFaceUp') return `${(match[ev.toSide || ev.side] && match[ev.toSide || ev.side].deckName) || '相手'}：「${cardName(uidToCardId(ev.uid))}」を表向きのまま証拠として得た`;
    if (ev.type === 'deckTopToEvidenceFaceUp') return `${sideLabel}：デッキの上を表向きで証拠として得た`;
    if (ev.type === 'cutInUse') return `${sideLabel}：「${cardName(uidToCardId(ev.uid))}」でカットインを使用`;
    if (ev.type === 'handReveal') return `${sideLabel}：手札を公開した（${(ev.cardIds || []).map(id => '「' + cardName(id) + '」').join('')}）`;
    if (ev.type === 'handDiscard') return `${sideLabel}：「${cardName(uidToCardId(ev.uid))}」をリムーブした`;
    if (ev.type === 'selfRemoveCost') return `${sideLabel}：「${cardName(uidToCardId(ev.uid))}」をリムーブした（コスト）`;
    if (ev.type === 'selfToDeckBottomCost') return `${sideLabel}：「${cardName(uidToCardId(ev.uid))}」をデッキの下に戻した（コスト）`;
    if (ev.type === 'declareSleepCost') return `${sideLabel}：「${cardName(uidToCardId(ev.uid))}」をスリープさせた（コスト）`;
    if (ev.type === 'declareSleepTarget') return `${sideLabel}：「${cardName(uidToCardId(ev.uid))}」をスリープさせた`;
    if (ev.type === 'apBuffApply') return `${sideLabel}：「${cardName(uidToCardId(ev.targetUid))}」をターン終了時までAP＋${ev.amount}`;
    if (ev.type === 'lpBuffApply') return `${sideLabel}：「${cardName(uidToCardId(ev.targetUid))}」をターン終了時までLP＋${ev.amount}`;
    if (ev.type === 'tempKeywordGrant') return `${sideLabel}：「${cardName(uidToCardId(ev.targetUid))}」にターン終了時まで〚${ev.keyword}〛を付与`;
    if (ev.type === 'tempContactWipeGrant') return `${sideLabel}：「${cardName(uidToCardId(ev.targetUid))}」にターン終了時までコンタクト相殺能力を付与`;
    if (ev.type === 'tempContactReentryGrant') return `${sideLabel}：「${cardName(uidToCardId(ev.targetUid))}」にターン終了時まで登場時効果を付与`;
    if (ev.type === 'tempDeclareGrant') return `${sideLabel}：「${cardName(uidToCardId(ev.targetUid))}」にターン終了時まで宣言能力を付与`;
    if (ev.type === 'lockCardName') return `${sideLabel}：このターン中「${ev.name}」を使用できなくした`;
    if (ev.type === 'boardWipe') return `${sideLabel}：現場の全キャラをリムーブした`;
    if (ev.type === 'boardWipeExcept') return `${sideLabel}：「${cardName(uidToCardId(ev.exceptUid))}」以外のすべてのキャラをリムーブした`;
    if (ev.type === 'boardWipeCard') return `${sideLabel}：現場一掃で「${cardName(uidToCardId(ev.uid))}」をリムーブ`;
    if (ev.type === 'fileToHand') return `${sideLabel}：FILEエリアから1枚を手札に加えた`;
    if (ev.type === 'millSelf') return `${sideLabel}：デッキの上から${ev.count}枚をリムーブした`;
    if (ev.type === 'misleadSleep') return `${sideLabel}：「${cardName(uidToCardId(ev.uid))}」でミスリードを使用`;
    if (ev.type === 'removeEventToHand') return `${sideLabel}：「${cardName(uidToCardId(ev.uid))}」を手札に加えた`;
    if (ev.type === 'fieldRemoveTrigger') {
      return ev.effectType === 'draw'
        ? `${sideLabel}：現場リムーブ時効果でカードを1枚引いた`
        : `${sideLabel}：現場リムーブ時効果で「${cardName(uidToCardId(ev.uid))}」をリムーブした`;
    }
    if (ev.type === 'solveCase') return `${sideLabel}：事件を解決してゲームに勝利した`;
    if (ev.type === 'solveCaseEvidenceMill') return `${sideLabel}：証拠を${ev.count}つリムーブして事件を解決してゲームに勝利した`;
    if (ev.type === 'disguiseSwap') return `${sideLabel}：「${cardName(ev.newCardId)}」に変装した`;
    if (ev.type === 'switchRemove') return `${sideLabel}：スイッチで「${cardName(uidToCardId(ev.uid))}」をリムーブ`;
    if (ev.type === 'nextHintDraw') return `${sideLabel}：ネクストヒントでFILEエリアの上から1枚を手札に加えた`;
    if (ev.type === 'assist') return `${sideLabel}：パートナーがアシストでFILEエリアに移動した`;
    if (ev.type === 'actionDeclare') {
      return `${sideLabel}：「${cardName(uidToCardId(ev.actorUid))}」が「${cardName(uidToCardId(ev.targetUid))}」にアクション宣言`;
    }
    if (ev.type === 'actionResolve') {
      if (!ev.guardUid && ev.targetType === 'case') {
        const targetLabel = (match[ev.targetSide] && match[ev.targetSide].deckName) || '相手';
        return `${sideLabel}：「${cardName(uidToCardId(ev.actorUid))}」のアクション［事件］がガードされず解決 → ${targetLabel}の証拠を1つリムーブ、${sideLabel}は証拠を1つ獲得`;
      }
      const defenderUid = ev.guardUid || ev.targetUid;
      const actorCard = CARD_BY_ID.get(uidToCardId(ev.actorUid));
      const defenderCard = CARD_BY_ID.get(uidToCardId(defenderUid));
      const cutInBonus = (sideKey) => (ev.cutInBuffs || []).filter(b => b.side === sideKey).reduce((s, b) => s + b.amount, 0);
      const actorAp = (actorCard?.ap || 0) + cutInBonus(ev.side);
      const defenderAp = (defenderCard?.ap || 0) + cutInBonus(ev.targetSide);
      const guardPart = ev.guardUid ? `「${cardName(uidToCardId(ev.guardUid))}」がガード／` : '';
      const result = actorAp >= defenderAp
        ? `「${cardName(uidToCardId(defenderUid))}」をリムーブ`
        : '何も起こらなかった';
      return `${sideLabel}：${guardPart}コンタクト（AP ${actorAp} vs ${defenderAp}）→ ${result}`;
    }
    if (ev.type === 'play') {
      const playedCardId = uidToCardId(ev.uid);
      const playedDef = CARD_BY_ID.get(playedCardId);
      return playedDef && playedDef.card_type === 'イベント'
        ? `${sideLabel}：「${cardName(playedCardId)}」を使用した`
        : `${sideLabel}：「${cardName(playedCardId)}」を現場に出した`;
    }
    if (ev.type === 'mulligan') {
      return ev.returnedUids.length === 0
        ? `${sideLabel}：マリガンしなかった`
        : `${sideLabel}：マリガンで${ev.returnedUids.length}枚引き直した`;
    }
    if (ev.type === 'reason') {
      const side = match[ev.side];
      const target = ev.targetType === 'partner' ? side.partner : side.field.find(c => c.uid === ev.uid);
      const cardId = target ? target.cardId : uidToCardId(ev.uid);
      const lp = target ? Math.max(0, effectiveLp(match, target) - (ev.lpReduction || 0)) : 0;
      return `${sideLabel}：「${cardName(cardId)}」が推理（証拠+${lp}）`;
    }
    if (ev.type === 'deckPeekChoose') {
      const parts = [`${sideLabel}：「${cardName(uidToCardId(ev.sourceUid))}」の登場時効果でデッキの上から${ev.revealedCount}枚確認`];
      parts.push(ev.chosenUid
        ? `「${cardName(uidToCardId(ev.chosenUid))}」を手札に加えた`
        : '手札に加えなかった');
      return parts.join('／');
    }
    if (ev.type === 'deckPeekRemove') {
      return `${sideLabel}：「${cardName(uidToCardId(ev.removedHandUid))}」をリムーブした`;
    }
    if (ev.type === 'deckPeekReorder') {
      return `${sideLabel}：残り${ev.remainingOrder.length}枚をデッキの下に戻した`;
    }
    if (ev.type === 'partnerHandRemove') {
      return `${sideLabel}：「${cardName(uidToCardId(ev.sourceUid))}」の登場時効果で「${cardName(uidToCardId(ev.removedHandUid))}」をリムーブした`;
    }
    if (ev.type === 'partnerFieldRemove') {
      return ev.targetUid
        ? `${sideLabel}：「${cardName(uidToCardId(ev.targetUid))}」をリムーブした`
        : `${sideLabel}：「${cardName(uidToCardId(ev.sourceUid))}」の登場時効果でキャラは選ばなかった`;
    }
    if (ev.type === 'sleepChar') return `${sideLabel}：「${cardName(uidToCardId(ev.uid))}」をスリープさせた`;
    if (ev.type === 'activateChar') return `${sideLabel}：「${cardName(uidToCardId(ev.uid))}」をアクティブにした`;
    if (ev.type === 'fieldToHand') return `${sideLabel}：「${cardName(uidToCardId(ev.uid))}」が手札に戻った`;
    if (ev.type === 'fieldToDeckBottom') return `${sideLabel}：「${cardName(uidToCardId(ev.uid))}」がデッキの下に移った`;
    if (ev.type === 'removeToField') return `${sideLabel}：リムーブエリアから「${cardName(uidToCardId(ev.uid))}」を登場させた`;
    if (ev.type === 'deckSearchUntil') {
      return ev.foundUid
        ? `${sideLabel}：「${cardName(uidToCardId(ev.sourceUid))}」の効果でデッキから「${cardName(uidToCardId(ev.foundUid))}」を見つけて手札に加え、デッキをシャッフルした`
        : `${sideLabel}：「${cardName(uidToCardId(ev.sourceUid))}」の効果でデッキを探したが見つからず、デッキをシャッフルした`;
    }
    if (ev.type === 'deckPeekMill') return `${sideLabel}：残り${ev.uids.length}枚をリムーブエリアに移した`;
    if (ev.type === 'stackUnder') return `${sideLabel}：「${cardName(uidToCardId(ev.hostUid))}」の下に${ev.uids.length}枚${ev.faceDown === false ? '表向きで' : ''}重ねた`;
    if (ev.type === 'setEvent') return `${sideLabel}：「${cardName(uidToCardId(ev.eventUid))}」を「${cardName(uidToCardId(ev.hostUid))}」にセットした`;
    if (ev.type === 'removeUnderEvent') return `${sideLabel}：「${cardName(uidToCardId(ev.eventUid))}」をリムーブした(セット効果発動)`;
    if (ev.type === 'refreshDeck') {
      const oppLabel = (match[otherSide(ev.side)] && match[otherSide(ev.side)].deckName) || (otherSide(ev.side) === 'self' ? '自分' : '相手');
      return `${sideLabel}：デッキが尽きたためリフレッシュした（${oppLabel}は証拠を1つ得た）`;
    }
    return JSON.stringify(ev);
  }

  // uidはカードidを含む形式("self-3"や"self-partner")ではないため、現在の盤面(手札/現場)から逆引きする
  function uidToCardId(uid){
    const all = [...match.self.hand, ...match.self.field, ...match.opponent.hand, ...match.opponent.field,
                 ...match.self.deckPile, ...match.opponent.deckPile, ...match.self.file, ...match.opponent.file,
                 ...match.self.evidence, ...match.opponent.evidence, ...match.self.remove, ...match.opponent.remove,
                 ...(match.self.case ? [match.self.case] : []), ...(match.opponent.case ? [match.opponent.case] : []),
                 ...match.self.field.flatMap(c => c.under || []), ...match.opponent.field.flatMap(c => c.under || []),
                 ...(match.self.partnerMR ? [match.self.partnerMR] : []), ...(match.opponent.partnerMR ? [match.opponent.partnerMR] : [])];
    const found = all.find(c => c.uid === uid);
    return found ? found.cardId : null;
  }

  function renderLog(){
    const log = document.getElementById('actionLog');
    log.style.display = 'block';
    if (match.events.length === 0) {
      log.innerHTML = '<div class="empty-hint">まだアクションはありません</div>';
      return;
    }
    log.innerHTML = match.events.map((ev, i) => {
      const isCurrent = replayMode && i === replayPointer - 1;
      return `<div class="entry${isCurrent ? ' current' : ''}">${i + 1}. ${describeEvent(ev)}</div>`;
    }).join('');
    if (replayMode) {
      const cur = log.querySelector('.entry.current');
      if (cur) cur.scrollIntoView({ block: 'nearest' });
    } else {
      log.scrollTop = log.scrollHeight;
    }
  }

  // ログは普段は隠しておき、「ログ」ボタンを押したときだけ出す(出しっぱなしだと盤面の邪魔になる)
  (function setupLogToggle(){
    if (document.body.classList.contains('online')) return;   // オンライン対戦ではログを出さない
    const btn = document.createElement('button');
    btn.id = 'logToggleBtn'; btn.className = 'btn small'; btn.textContent = '📜 ログ';
    btn.onclick = () => { const on = document.body.classList.toggle('log-open'); btn.textContent = on ? '✕ ログを閉じる' : '📜 ログ'; };
    document.body.appendChild(btn);
  })();

  // ---- セットアップ画面 ----
  function populateDeckSelects(){
    const decks = loadSavedDecks();
    const selfSel = document.getElementById('selfDeckSelect');
    const oppSel = document.getElementById('oppDeckSelect');
    if (decks.length === 0) {
      selfSel.innerHTML = oppSel.innerHTML = '<option>保存されたデッキがありません</option>';
      document.getElementById('startBtn').disabled = true;
      return;
    }
    const opts = decks.map((d, i) => `<option value="${i}">${d.name}（${d.cards.reduce((a,c)=>a+c.qty,0)}枚）</option>`).join('');
    selfSel.innerHTML = opts;
    oppSel.innerHTML = opts;
    if (decks.length > 1) oppSel.selectedIndex = 1;
  }

  function startMatch(){
    const decks = loadSavedDecks();
    const selfDeck = decks[Number(document.getElementById('selfDeckSelect').value)];
    const oppDeck = decks[Number(document.getElementById('oppDeckSelect').value)];
    if (!selfDeck || !oppDeck) return;
    startMatchWith(selfDeck, oppDeck, document.getElementById('firstPlayerSelect').value === 'opponent' ? 'opponent' : 'self');
  }

  // デッキ2つと先攻から対戦を始める本体(オンライン対戦はjs/online-layer.jsから直接呼ぶ)
  function startMatchWith(selfDeck, oppDeck, firstPlayer){
    const selfConfig = splitDeck(selfDeck);
    const oppConfig = splitDeck(oppDeck);

    match = {
      config: { self: selfConfig, opponent: oppConfig },
      self: buildSideState('self', selfConfig),
      opponent: buildSideState('opponent', oppConfig),
      events: [],
      turn: null,
      firstPlayer: firstPlayer === 'opponent' ? 'opponent' : 'self',
      gameOver: false,
    };
    replayMode = false;

    document.getElementById('setupPanel').style.display = 'none';
    document.getElementById('board').style.display = 'block';
    document.getElementById('replayControls').style.display = 'none';
    renderHeaderActionsForPlay();
    renderBoard(match);
    renderLog();
    fitRotatedTable();

    startMulliganPhase();
  }

  // ---- マリガン(初手5枚のうち好きな枚数をシャッフルして引き直す。先攻→後攻の順に1回ずつ) ----
  let mulliganPhase = null; // null(進行中でない) | 'self' | 'opponent'
  const mulliganSelected = new Set();

  function startMulliganPhase(){
    mulliganPhase = match.firstPlayer;
    mulliganSelected.clear();
    renderMulliganPanel();
  }

  function performMulligan(side, returnedUids){
    const s = match[side];
    const returning = s.hand.filter(c => returnedUids.includes(c.uid));
    const keptHand = s.hand.filter(c => !returnedUids.includes(c.uid));
    s.hand = keptHand;
    const resultDeck = shuffled([...s.deckPile, ...returning]);
    const ev = { type: 'mulligan', side, returnedUids, resultDeck };
    match.events.push(ev);
    applyEvent(match, ev);
    renderBoard(match);
    renderLog();

    if (mulliganPhase === match.firstPlayer) {
      mulliganPhase = match.firstPlayer === 'self' ? 'opponent' : 'self';
      mulliganSelected.clear();
      renderMulliganPanel();
    } else {
      mulliganPhase = null;
      document.getElementById('mulliganPanel').style.display = 'none';
      renderBoard(match); // ドロー/プレイ操作を有効化するため再描画
      startTurn(match.firstPlayer, 1, true); // 先攻側からターン1のオートフェイズを開始
    }
  }

  function renderMulliganPanel(){
    const panel = document.getElementById('mulliganPanel');
    if (!mulliganPhase) { panel.style.display = 'none'; return; }
    panel.style.display = 'flex';
    const sideLabel = (match[mulliganPhase] && match[mulliganPhase].deckName) || (mulliganPhase === 'self' ? '自分' : '相手');
    document.getElementById('mulliganTitle').textContent = `${sideLabel}のマリガン`;
    const grid = document.getElementById('mulliganHandGrid');
    grid.innerHTML = '';
    match[mulliganPhase].hand.forEach(c => {
      const tile = document.createElement('div');
      tile.className = 'mulligan-card' + (mulliganSelected.has(c.uid) ? ' selected' : '');
      tile.innerHTML = `<img src="${cardImage(c.cardId)}" alt="${cardName(c.cardId)}">`;
      tile.title = cardName(c.cardId);
      tile.onclick = () => {
        if (mulliganSelected.has(c.uid)) mulliganSelected.delete(c.uid); else mulliganSelected.add(c.uid);
        renderMulliganPanel();
      };
      grid.appendChild(tile);
    });
    document.getElementById('mulliganConfirmBtn').textContent =
      mulliganSelected.size > 0 ? `選んだ${mulliganSelected.size}枚を引き直す` : '引き直さずに進める';
  }

  function renderHeaderActionsForPlay(){
    document.getElementById('headerActions').innerHTML = `
      <button class="btn ghost" onclick="location.href='index.html'">← ホームに戻る</button>
      <button class="btn" id="saveReplayBtn">💾 対戦をファイルに保存</button>
    `;
    document.getElementById('saveReplayBtn').onclick = saveReplayToFile;
  }

  function saveReplayToFile(){
    const data = {
      version: 1,
      createdAt: new Date().toISOString(),
      self: match.config.self,
      opponent: match.config.opponent,
      firstPlayer: match.firstPlayer,
      events: match.events,
    };
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    const stamp = data.createdAt.replace(/[:.]/g, '-');
    a.href = url;
    a.download = `conan-tcg-replay_${stamp}.json`;
    document.body.appendChild(a);
    a.click();
    a.remove();
    URL.revokeObjectURL(url);
  }

  // ---- リプレイ読み込み ----
  document.getElementById('replayFileInput').addEventListener('change', (e) => {
    const file = e.target.files[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = () => {
      try {
        const data = JSON.parse(reader.result);
        startReplay(data);
      } catch (err) {
        alert('リプレイファイルの読み込みに失敗しました: ' + err.message);
      }
    };
    reader.readAsText(file);
  });

  function startReplay(data){
    match = {
      config: { self: data.self, opponent: data.opponent },
      self: buildSideState('self', data.self),
      opponent: buildSideState('opponent', data.opponent),
      firstPlayer: data.firstPlayer || 'self', // 古い保存ファイル(先攻選択機能追加前)は自分が先攻だったとみなす
      events: data.events || [],
    };
    replayMode = true;
    replayPointer = 0;

    document.getElementById('setupPanel').style.display = 'none';
    document.getElementById('board').style.display = 'block';
    document.getElementById('replayControls').style.display = 'flex';
    document.getElementById('headerActions').innerHTML = `
      <button class="btn ghost" onclick="exitReplayToHome()">← ホームに戻る</button>
      <span style="font-size:12px; opacity:.75;">📼 リプレイ再生中：${data.self.deckName} vs ${data.opponent.deckName}</span>
    `;
    // リプレイ再生中だけ、タスクバーも隠れる全画面表示に自動で切り替える
    if (window.electronAPI) window.electronAPI.setFullscreen(true);
    // リプレイ中は実際のカードゲームと同じく「〇〇してください」等の操作指示は出さず、
    // 下のログだけで内容が分かるようにする
    document.getElementById('actionHintBar').style.visibility = 'hidden';
    renderBoard(match);
    renderLog();
    renderTurnBar();
    fitRotatedTable();
    updateReplayControls();
  }

  // リプレイの「ホームに戻る」：全画面表示を解除してからホーム画面に戻る
  function exitReplayToHome(){
    if (window.electronAPI) window.electronAPI.setFullscreen(false);
    location.href = 'index.html';
  }
  function resetReplayState(){
    match.self = buildSideState('self', match.config.self);
    match.opponent = buildSideState('opponent', match.config.opponent);
  }

  // リプレイ再生：各イベント種別に応じて、実際の対戦中に見えていたのと同じ
  // アニメーション(カードが飛ぶ／登場する／光る等)を挟んでから状態を反映する。
  // 対応表にない種別(バフ適用やターン開始等、視覚的な移動を伴わないもの)は
  // アニメーションなしで即座に反映する
  function playReplayEventAnimation(ev, onDone){
    const side = ev.side;
    const apply = () => { applyEvent(match, ev); renderBoard(match); renderLog(); };
    const FLY_MS = 340;

    function simpleFly(fromSel, toSelAfter, faceImg){
      const fromEl = fromSel ? document.querySelector(fromSel) : null;
      const snap = fromEl ? snapshotCardPosition(fromEl) : null;
      apply();
      const toEl = toSelAfter ? document.querySelector(toSelAfter) : null;
      if (snap && toEl) { flyGhostCard(snap, toEl, faceImg); setTimeout(onDone, FLY_MS); }
      else onDone();
    }
    function simpleFade(fromSel, toSelAfter){
      const fromEl = fromSel ? document.querySelector(fromSel) : null;
      apply();
      const toEl = toSelAfter ? document.querySelector(toSelAfter) : null;
      if (fromEl && toEl) { fadeDrawCard(fromEl, toEl); setTimeout(onDone, FLY_MS); }
      else onDone();
    }
    // 手札／現場のカードがリムーブエリアへ飛んでいく系(カットイン使用・手札リムーブ・
    // スイッチ・宣言コスト等)の共通処理
    function flyToRemove(fromSel){
      const fromEl = document.querySelector(fromSel);
      const snap = fromEl ? snapshotCardPosition(fromEl) : null;
      const cardId = uidToCardId(ev.uid);
      apply();
      const toEl = document.querySelector(`.zone[data-side="${side}"] .remove-top`);
      if (snap && toEl) { flyGhostCard(snap, toEl, cardImage(cardId)); setTimeout(onDone, FLY_MS); }
      else onDone();
    }

    switch (ev.type) {
      case 'draw':
        simpleFade(`.zone[data-side="${side}"] .cardback-face`, `.zone[data-side="${side}"] .hand-row .card-menu-wrap:last-child .hcard`);
        return;
      case 'addFile':
        simpleFly(`.zone[data-side="${side}"] .cardback-face`, `.zone[data-side="${side}"] .file-stack .file-card-back:last-child`);
        return;
      case 'addEvidence':
        simpleFly(`.zone[data-side="${side}"] .cardback-face`, `.zone[data-side="${side}"] .evidence-stack .evi-card-back:last-child`);
        return;
      case 'fileToHand':
      case 'nextHintDraw':
        simpleFade(`.zone[data-side="${side}"] .file-stack .file-card-back:last-child`, `.zone[data-side="${side}"] .hand-row .card-menu-wrap:last-child .hcard`);
        return;
      case 'assist': {
        const partnerEl = document.querySelector(`.zone[data-side="${side}"] .partner-slot`);
        const partnerImg = match[side].partner ? cardImage(match[side].partner.cardId) : null;
        apply();
        const toEl = document.querySelector(`.zone[data-side="${side}"] .file-stack .assist-file-card`);
        if (partnerEl && toEl) { flyGhostCard(partnerEl, toEl, partnerImg); setTimeout(onDone, FLY_MS); }
        else onDone();
        return;
      }
      case 'reason': {
        // 得る証拠の枚数を、applyEvent内と同じロジックで事前に計算しておく
        const s = match[side];
        const target = ev.targetType === 'partner' ? s.partner : s.field.find(c => c.uid === ev.uid);
        const c = target ? defOfInst(target) : null;
        let baseLp = c && c.lp != null ? c.lp : 0;
        if (match.turn && match.turn.tempLpBuffs && target) {
          baseLp += match.turn.tempLpBuffs.filter(b => b.uid === target.uid).reduce((sum, b) => sum + b.amount, 0);
        }
        const lp = Math.max(0, baseLp - (ev.lpReduction || 0));
        const gainCount = Math.max(0, Math.min(lp, s.deckPile.length));
        const oldEvidenceCount = s.evidence.length;
        const deckEl = document.querySelector(`.zone[data-side="${side}"] .cardback-face`);
        apply();
        if (gainCount === 0) { onDone(); return; }
        const stack = document.querySelector(`.zone[data-side="${side}"] .evidence-stack`);
        const backs = stack ? Array.from(stack.querySelectorAll('.evi-card-back')) : [];
        for (let k = 0; k < gainCount; k++) { const el = backs[oldEvidenceCount + k]; if (el) el.style.visibility = 'hidden'; }
        let i = 0;
        const flyNext = () => {
          if (i >= gainCount) { onDone(); return; }
          const toEl = backs[oldEvidenceCount + i];
          i++;
          if (toEl) flyGhostCard(deckEl, toEl);
          if (i < gainCount) setTimeout(flyNext, AUTO_PHASE_STEP_MS);
          else setTimeout(onDone, FLY_MS);
        };
        flyNext();
        return;
      }
      case 'play': {
        const cardDef = CARD_BY_ID.get(uidToCardId(ev.uid));
        const isEventCard = cardDef && cardDef.card_type === 'イベント';
        const handEl = document.querySelector(`.zone[data-side="${side}"] .hand-row .hcard[data-uid="${ev.uid}"]`);
        if (isEventCard) {
          // イベントは「登場」ではなく「使用」：手札からリムーブエリアへ飛ばし、
          // 発動を強調する中央のポップアップを見せてから次に進む(ライブ再生と同じ演出)
          const fromSnapshot = handEl ? snapshotCardPosition(handEl) : null;
          apply();
          const toEl = document.querySelector(`.zone[data-side="${side}"] .remove-top`);
          if (fromSnapshot && toEl) flyGhostCard(fromSnapshot, toEl, cardImage(cardDef.id));
          playCutInEffect(cardDef.id, () => { showCardSpotlight(cardDef.id); onDone(); });
          return;
        }
        const fromRect = handEl ? handEl.getBoundingClientRect() : null;
        if (cardDef) showCardSpotlight(cardDef.id);
        apply();
        const fieldEl = document.querySelector(`.zone[data-side="${side}"] .field-row .char-card[data-uid="${ev.uid}"]`);
        if (fromRect && fieldEl) { animateCardEntry(fieldEl, fromRect, onDone); }
        else onDone();
        return;
      }
      case 'actionResolve': {
        const defenderUid = ev.guardUid || ev.targetUid;
        const defenderEl = document.querySelector(`.zone[data-side="${ev.targetSide}"] .field-row .char-card[data-uid="${defenderUid}"]`);
        const snap = defenderEl ? snapshotCardPosition(defenderEl) : null;
        const cardId = uidToCardId(defenderUid);
        const finishFly = () => {
          apply();
          const outcome = getFieldRemovalOutcome(ev.targetSide, defenderUid);
          if (outcome.happened && snap) {
            const toEl = document.querySelector(`.zone[data-side="${ev.targetSide}"] ${outcome.redirected ? '.partner-mr-slot' : '.remove-top'}`);
            if (toEl) { flyGhostCard(snap, toEl, cardImage(cardId)); setTimeout(onDone, FLY_MS); return; }
          }
          onDone();
        };
        // 実際にキャラ同士がぶつかったコンタクト(事件アクションがガードされずスルーした
        // だけの場合を除く)なら、ライブ再生と同じ「左右から中央にぶつかる」演出を挟む
        const isRealFight = defenderEl && (ev.targetType !== 'case' || !!ev.guardUid);
        if (isRealFight) {
          const attackerCardId = uidToCardId(ev.actorUid);
          // 除去されるかどうかはapplyEvent側の判定と同じ式で、イベントに記録済みの
          // AP比較材料(cutInBuffs/immuneUids)から事前に計算しておく
          const targetState = match[ev.targetSide];
          const defenderInstance = targetState.field.find(c => c.uid === defenderUid);
          const attackerInstance = match[ev.side].field.find(c => c.uid === ev.actorUid);
          const cutInBonus = (sideKey) => (ev.cutInBuffs || []).filter(b => b.side === sideKey).reduce((s, b) => s + b.amount, 0);
          const actorAp = attackerInstance ? effectiveAp(match, attackerInstance, ev.side) + cutInBonus(ev.side) : 0;
          const defAp = defenderInstance ? effectiveAp(match, defenderInstance, ev.targetSide) + cutInBonus(ev.targetSide) : 0;
          const willRemove = !!(attackerInstance && defenderInstance && actorAp >= defAp && !(ev.immuneUids || []).includes(defenderUid));
          if (attackerCardId != null && cardId != null) {
            const attackerBuffs = attackerInstance
              ? getApBuffSources(match, attackerInstance, ev.side, (ev.cutInBuffs || []).filter(b => b.side === ev.side)) : [];
            const defenderBuffs = defenderInstance
              ? getApBuffSources(match, defenderInstance, ev.targetSide, (ev.cutInBuffs || []).filter(b => b.side === ev.targetSide)) : [];
            // 演出上の左右は、攻撃/防御ではなく実際の画面上の位置(自分＝左、相手＝右)に合わせる
            const attackerIsSelf = ev.side === 'self';
            const leftCardId = attackerIsSelf ? attackerCardId : cardId;
            const rightCardId = attackerIsSelf ? cardId : attackerCardId;
            const leftBuffs = attackerIsSelf ? attackerBuffs : defenderBuffs;
            const rightBuffs = attackerIsSelf ? defenderBuffs : attackerBuffs;
            const removedSide = willRemove ? (attackerIsSelf ? 'right' : 'left') : null;
            playClashEffect(leftCardId, rightCardId, removedSide, finishFly, leftBuffs, rightBuffs);
            return;
          }
        }
        finishFly();
        return;
      }
      case 'cutInUse':
        playCutInEffect(uidToCardId(ev.uid));
        flyToRemove(`.zone[data-side="${side}"] .hand-row .hcard[data-uid="${ev.uid}"]`);
        return;
      case 'handDiscard':
        flyToRemove(`.zone[data-side="${side}"] .hand-row .hcard[data-uid="${ev.uid}"]`);
        return;
      case 'selfRemoveCost':
      case 'switchRemove':
      case 'boardWipeCard':
        flyToRemove(`.zone[data-side="${side}"] .field-row .char-card[data-uid="${ev.uid}"]`);
        return;
      case 'selfToDeckBottomCost': {
        const fieldEl = document.querySelector(`.zone[data-side="${side}"] .field-row .char-card[data-uid="${ev.uid}"]`);
        const cardId = uidToCardId(ev.uid);
        showCardSpotlight(cardId);
        const finish = () => {
          const snap = fieldEl ? snapshotCardPosition(fieldEl) : null;
          apply();
          const deckEl = document.querySelector(`.zone[data-side="${side}"] .cardback-face`);
          if (snap && deckEl) { flyGhostCard(snap, deckEl, cardImage(cardId)); setTimeout(onDone, FLY_MS); }
          else onDone();
        };
        if (fieldEl) {
          fieldEl.classList.add('landing-flash');
          setTimeout(() => { fieldEl.classList.remove('landing-flash'); finish(); }, 500);
        } else {
          finish();
        }
        return;
      }
      case 'disguiseSwap': {
        playCutInEffect(ev.newCardId);
        apply();
        const fieldEl = document.querySelector(`.zone[data-side="${side}"] .field-row .char-card[data-uid="${ev.uid}"]`);
        if (fieldEl) { fieldEl.classList.add('landing-flash'); setTimeout(() => { fieldEl.classList.remove('landing-flash'); onDone(); }, 500); }
        else onDone();
        return;
      }
      case 'millSelf': {
        // ミステリーコースター等：デッキの上からN枚をリムーブエリアへ1枚ずつ飛ばす
        // (古いリプレイではNがまとめて1件で記録されている場合もあるため、
        // count>1でもここで1枚ずつのアニメーションに分解する)
        const s = match[side];
        const n = Math.min(ev.count, s.deckPile.length);
        const cardIds = s.deckPile.slice(0, n).map(c => c.cardId);
        const deckEl = document.querySelector(`.zone[data-side="${side}"] .cardback-face`);
        apply();
        if (n === 0) { onDone(); return; }
        const toEl = document.querySelector(`.zone[data-side="${side}"] .remove-top`);
        let i = 0;
        const flyNext = () => {
          if (i >= n) { onDone(); return; }
          const cid = cardIds[i];
          i++;
          if (deckEl && toEl) flyGhostCard(deckEl, toEl, cardImage(cid));
          if (i < n) setTimeout(flyNext, AUTO_PHASE_STEP_MS);
          else setTimeout(onDone, FLY_MS);
        };
        flyNext();
        return;
      }
      case 'fieldRemoveTrigger': {
        if (ev.effectType === 'draw') {
          simpleFade(`.zone[data-side="${side}"] .cardback-face`, `.zone[data-side="${side}"] .hand-row .card-menu-wrap:last-child .hcard`);
          return;
        }
        if (ev.effectType === 'handRemoveByUid') {
          flyToRemove(`.zone[data-side="${side}"] .hand-row .hcard[data-uid="${ev.uid}"]`);
          return;
        }
        apply();
        onDone();
        return;
      }
      default:
        apply();
        onDone();
    }
  }
  function replayNext(){
    if (replayAnimating || replayPointer >= match.events.length) return;
    replayAnimating = true;
    const ev = match.events[replayPointer];
    playReplayEventAnimation(ev, () => {
      replayPointer++;
      replayAnimating = false;
      updateReplayControls();
      if (replayAutoPlaying) {
        if (replayPointer >= match.events.length) { stopAutoPlay(); return; }
        replayTimer = setTimeout(replayNext, 260);
      }
    });
  }

  function replayPrev(){
    if (replayPointer <= 0) return;
    const target = replayPointer - 1;
    resetReplayState();
    replayPointer = 0;
    while (replayPointer < target) { applyEvent(match, match.events[replayPointer]); replayPointer++; }
    renderBoard(match);
    renderLog();
    updateReplayControls();
  }

  function replayReset(){
    stopAutoPlay();
    resetReplayState();
    replayPointer = 0;
    renderBoard(match);
    renderLog();
    updateReplayControls();
  }

  function stopAutoPlay(){
    replayAutoPlaying = false;
    if (replayTimer) { clearTimeout(replayTimer); replayTimer = null; }
    const btn = document.getElementById('replayPlayBtn');
    if (btn) btn.textContent = '▶ 自動再生';
  }

  // 自動再生：各ステップのアニメーションが終わってから次へ進む(replayNext内で
  // 自己スケジュールする)ので、ここではフラグを立てて最初の1手を進めるだけでよい
  function toggleAutoPlay(){
    if (replayAutoPlaying) { stopAutoPlay(); return; }
    if (replayPointer >= match.events.length) return;
    replayAutoPlaying = true;
    document.getElementById('replayPlayBtn').textContent = '⏸ 停止';
    replayNext();
  }

  function updateReplayControls(){
    document.getElementById('replayStepCount').textContent = `${replayPointer} / ${match.events.length}`;
    document.getElementById('replayPrevBtn').disabled = replayPointer === 0;
    document.getElementById('replayNextBtn').disabled = replayPointer >= match.events.length;
    if (replayPointer >= match.events.length) stopAutoPlay();
  }

  document.getElementById('startBtn').onclick = startMatch;
  document.getElementById('gameOverCloseBtn').onclick = () => {
    document.getElementById('gameOverOverlay').style.display = 'none';
  };
  document.getElementById('mulliganConfirmBtn').onclick = () => {
    performMulligan(mulliganPhase, [...mulliganSelected]);
  };
  document.getElementById('replayNextBtn').onclick = replayNext;
  document.getElementById('replayPrevBtn').onclick = replayPrev;
  document.getElementById('replayResetBtn').onclick = replayReset;
  document.getElementById('replayPlayBtn').onclick = toggleAutoPlay;
  // リプレイ中は、動画プレイヤーのように盤面をクリックするだけで再生/一時停止を
  // 切り替えられるようにする(実際の対戦中はreplayModeがfalseなので影響しない)
  document.getElementById('board').addEventListener('click', () => {
    if (replayMode) toggleAutoPlay();
  });

  // 90度回転した盤面全体を、画面に収まるように縮小する
  function fitRotatedTable(retry){
    const table = document.querySelector('.table');
    const wrap = document.querySelector('.table-rotate-wrap');
    const board = document.getElementById('board');
    const header = document.querySelector('header');
    if (!table || !wrap || !board || getComputedStyle(board).display === 'none') return;
    // 前回のwrapサイズが残っていると測定に影響しうるため、測定前に一旦解除する
    wrap.style.width = 'auto';
    wrap.style.height = 'auto';
    table.style.transform = 'translate(-50%, -50%) rotate(90deg) scale(1)';
    // rotate(90deg)により見た目の幅/高さが元の高さ/幅と入れ替わる。transformは
    // レイアウト上のサイズに影響しないため、.table-rotate-wrapの幅/高さを
    // 回転後の実寸に明示的に合わせることで、ページ全体の高さも縮小分だけ小さくなる
    const rect = table.getBoundingClientRect();
    const headerHeight = header ? header.getBoundingClientRect().height : 0;
    // board.clientWidth はpadding込みのサイズなので、左右のpadding(26+26=52)を
    // 差し引かないと実際に描画できる幅より広く見積もってしまい、右端(デッキ等)が
    // はみ出す原因になる。フォント/環境差を吸収する余白(20)も追加で引いておく
    const availableWidth = board.clientWidth - 52 - 20;
    // .boardのpadding(上16+下40=56)に加えて、フォント/画像読み込みによる
    // 微妙なズレを吸収する余白(24)も引いておく
    const availableHeight = document.documentElement.clientHeight - headerHeight - 56 - 24;
    // 現場にキャラカード5枚が並ぶ最低限の見やすさは確保したいので、
    // 画面が小さくてもこれ以上は縮小しない下限を設ける(下限を下回る場合は
    // 画面内に収めるのをあきらめてスクロールさせる)
    const MIN_SCALE = 0.4;
    const rawScale = Math.min(availableWidth / rect.width, availableHeight / rect.height, 1);
    const scale = Math.max(rawScale, MIN_SCALE);
    table.style.transform = `translate(-50%, -50%) rotate(90deg) scale(${scale})`;
    wrap.style.width = (rect.width * scale) + 'px';
    wrap.style.height = (rect.height * scale) + 'px';
    // 計算結果が想定通りか実測で検算し、それでもboardからはみ出していれば
    // (フォント差など計算に含められない要因があった場合の保険として)
    // はみ出した分だけ追加でスケールを縮める
    const wrapRect = wrap.getBoundingClientRect();
    const boardRect = board.getBoundingClientRect();
    const overflowX = wrapRect.right - boardRect.right;
    const overflowY = wrapRect.bottom - boardRect.bottom;
    if (overflowX > 1 || overflowY > 1) {
      const shrinkX = overflowX > 1 ? (wrapRect.width - overflowX) / wrapRect.width : 1;
      const shrinkY = overflowY > 1 ? (wrapRect.height - overflowY) / wrapRect.height : 1;
      // デッキ・リムーブエリアが画面外に切れる方が、カードが少し小さくなるより
      // 悪いので、この最終補正だけはMIN_SCALEの下限を無視してでも必ず収める
      const correctedScale = scale * Math.min(shrinkX, shrinkY) * 0.98;
      table.style.transform = `translate(-50%, -50%) rotate(90deg) scale(${correctedScale})`;
      wrap.style.width = (rect.width * correctedScale) + 'px';
      wrap.style.height = (rect.height * correctedScale) + 'px';
    }
    // フォント/画像の読み込みタイミングでheaderの高さ等が後から変わることがあるため、
    // 少し遅らせてもう一度だけ計算し直す
    if (!retry) setTimeout(() => fitRotatedTable(true), 200);
  }
  window.addEventListener('resize', () => fitRotatedTable());

  populateDeckSelects();

  // ホーム画面の「リプレイ再生」一覧からリプレイを選んだ場合、sessionStorage経由で
  // 読み込むデータが渡されてくるので、あればそのまま再生を開始する
  (function loadReplayFromHomeIfAny(){
    const raw = sessionStorage.getItem('conanTcgReplayToLoad');
    if (!raw) return;
    sessionStorage.removeItem('conanTcgReplayToLoad');
    try {
      startReplay(JSON.parse(raw));
    } catch (err) {
      alert('リプレイの読み込みに失敗しました: ' + err.message);
    }
  })();
